window.SINUSAL_P2_DADOS={"fontes":[{"id":"p2c","titulo":"P2 · Turma C","sub":"Transcrição de aluno (texto digitado), 20 questões","pags":"79–82","n":20},{"id":"p2d","titulo":"P2 · Turma D","sub":"Folha digitada, 20 questões","pags":"90–95","n":20},{"id":"reg24","titulo":"Segunda prueba de regularización · 2024","sub":"Foto da folha original, Turma C, 7 questões","pags":"5","n":7},{"id":"rec23","titulo":"Segunda prueba recuperatoria · 09/06/2023","sub":"Foto da folha original, 15 questões","pags":"96 e 98","n":15},{"id":"p2f1","titulo":"P2 · foto, questões 9 a 14","sub":"Foto da folha original (página 97, parte de cima)","pags":"97","n":6},{"id":"p2f2","titulo":"P2 · foto, Secciones I a IV","sub":"Foto da folha original (página 97, parte de baixo)","pags":"97","n":8},{"id":"par1","titulo":"1º Parcial · Anatomía Patológica I","sub":"Folha digitada; questões de necrose, apoptose, acumulação e adaptação","pags":"99–103","n":15},{"id":"p1c","titulo":"P1 · Turma C","sub":"Transcrição de aluno; questões de necrose, apoptose, acumulação e adaptação","pags":"83–86","n":16},{"id":"par1r","titulo":"1º Parcial + Recuperación","sub":"Folha digitada; questões de necrose, apoptose, acumulação e adaptação","pags":"87–89","n":16},{"id":"final24","titulo":"Examen Final Complementario · 21/02/2024","sub":"Foto da folha original (págs. 1–4) e transcrição digitada (págs. 104–110); só as questões da P2","pags":"1–4 e 104–110","n":23},{"id":"f24t","titulo":"Examen Final 21/02/2024 · transcrição","sub":"Transcrição digitada com respostas em negrito (págs. 104–110), na numeração dela: inflamação crônica, granulomas, reparação, adaptação e a de mediadores. Na foto da folha (págs. 1–4) as mesmas questões têm outro número.","pags":"104–110","n":17},{"id":"robbins","titulo":"Banco Robbins · Inflamación","sub":"Prints do banco de questões do Robbins (1 pergunta por página, gabarito \"CORRECTO\" no topo)","pags":"19–58","n":23},{"id":"pef","titulo":"Banco PEF · cap. 3 Inflamación y reparación","sub":"Páginas digitalizadas do livro de perguntas (o X marca a certa). Fora as que ela já copiou: 11, 15, 25 e 27.","pags":"59–78","n":24},{"id":"p2_26","titulo":"2ª parcial · 06/11/2026 · 5º F","sub":"Foto da folha original (Fila 1, págs. 2 e 3) + gabarito oficial manuscrito","pags":"111–113","n":17},{"id":"r26g","titulo":"2ª parcial 2026 · 5º G · correção em aula","sub":"Gabarito oficial manuscrito (Filas 1 a 4) + questões que ela leu e respondeu na correção (gravação)","pags":"114","n":16},{"id":"p1g26","titulo":"1ª parcial 2026 · gabaritos 5º F e 5º G","sub":"Gabaritos oficiais manuscritos; enunciados reconstruídos a partir das respostas","pags":"115–117","n":24}],"qs":[{"p":"p2c","n":1,"t":"cita","tema":"pig","q":"Cite 2 pigmentos de hemoglobina:","a":"Bilirrubina y hemosiderina.","e":"Os dois vêm do heme: a hemosiderina guarda o ferro (fica em macrófagos e cora com azul da Prússia) e a bilirrubina é a parte sem ferro (icterícia). Hematoidina também deriva da Hb, mas a dupla que ela espera é essa."},{"p":"p2c","n":2,"t":"cita","tema":"inf","q":"Dos cambios vasculares característicos de la inflamación aguda:","a":"Vasodilatación y aumento de la permeabilidad vascular.","e":"A vasoconstrição arteriolar dura segundos e não é característica (o próprio aluno anotou isso). A estase é consequência dos dois primeiros."},{"p":"p2c","n":3,"t":"cita","tema":"inf","q":"Dos sustancias quimiotácticas endógenas de origen celular:","a":"IL-8 (CXCL8) y leucotrieno B4.","e":"Endógena quer dizer produzida pelo hospedeiro; de origem celular exclui as plasmáticas. Por isso C5a (plasma) e produtos bacterianos (exógenos) não servem. PAF e outras quimiocinas também valeriam. A PGD2 que o aluno citou é quimiotática para eosinófilos, resposta arriscada."},{"p":"p2c","n":4,"t":"comp","tema":"c7","q":"La tinción ________ muestra depósito de material amiloide de color verde manzana al observar al microscopio de luz polarizada.","a":"Rojo Congo.","e":"No microscópio comum o amiloide fica rosa-avermelhado com vermelho Congo; na luz polarizada aparece a birrefringência verde-maçã, por causa da estrutura em folha β-pregueada."},{"p":"p2c","n":5,"t":"comp","tema":"pig","q":"Las llamadas células de insuficiencia cardíaca corresponden a macrófagos alveolares cargados de ________.","a":"Hemosiderina.","e":"Na insuficiência cardíaca esquerda a congestão pulmonar extravasa hemácias para o alvéolo; os macrófagos degradam a Hb e guardam o ferro como hemosiderina. Não é biliverdina nem bilirrubina (pegadinha da Turma D, Q15)."},{"p":"p2c","n":6,"t":"comp","tema":"inf","q":"Se denomina ________ al movimiento de los leucocitos por los tejidos hacia el sitio de lesión por productos bacterianos.","a":"Quimiotaxis.","e":"Locomoção orientada por gradiente químico. Quimiotáticos exógenos: produtos bacterianos. Endógenos: quimiocinas (IL-8), C5a e LTB4."},{"p":"p2c","n":7,"t":"comp","tema":"c7","q":"En el proceso de calcificación patológica, la organela en la que se deposita el calcio es ________.","a":"Mitocondria.","e":"Na calcificação intracelular o cálcio se concentra nas mitocôndrias das células mortas ou morrendo, que perdem o controle do Ca²⁺. No espaço extracelular a nucleação começa em vesículas ligadas à membrana."},{"p":"p2c","n":8,"t":"comp","tema":"c7","q":"En la deficiencia de alfa-1 antitripsina se observan depósitos globulares eosinófilos de una proteína en los hepatocitos; su carencia causa en los pacientes ________.","a":"Enfisema pulmonar.","e":"A AAT mal dobrada fica presa no retículo do hepatócito (glóbulos positivos para ácido periódico de Schiff (PAS) resistentes à diastase) e falta no sangue. Sem ela a elastase dos neutrófilos destrói os alvéolos: enfisema panacinar. No fígado o acúmulo causa hepatite e cirrose."},{"p":"p2c","n":9,"t":"cita","tema":"pig","q":"Una paciente de 4 años… [enunciado cortado en la transcripción]","a":"Polvo de carbón (antracosis).","e":"Antracose é o pigmento exógeno mais comum: o carvão inalado é captado pelos macrófagos alveolares e levado aos linfonodos traqueobrônquicos.","nt":"A transcrição só guardou o começo do caso. A resposta anotada (pó de carvão) mostra que era a questão de pigmento exógeno."},{"p":"p2c","n":10,"t":"cita","tema":"c7","q":"Mujer sana de 73 años cae por las escaleras y se lesiona la cadera derecha. No hay fractura, pero la radiografía revela calcificación de las pequeñas arterias musculares laterales al útero.","a":"Esclerosis medial calcificada (de Mönckeberg), que es una calcificación distrófica.","e":"Idosa saudável, sem hipercalcemia, com cálcio na camada média de artérias musculares: é Mönckeberg, uma forma de calcificação distrófica. Responder \"metastásica\" é o erro clássico, porque metastásica exige hipercalcemia.","nt":"Quando ela dá o quadro de opções (P2 da p. 97, Q3) a resposta esperada é literalmente \"Esclerosis medial calcificada\"."},{"p":"p2c","n":11,"t":"cita","tema":"c7","q":"¿Cuál de los siguientes depósitos corresponde a una calcificación distrófica?","a":"Cuerpos de psamoma.","e":"Psamoma é calcificação distrófica em lâminas concêntricas sobre papilas necrosadas: carcinoma papilar de tireoide, cistoadenocarcinoma seroso de ovário, meningioma e mesotelioma.","nt":"A transcrição só guardou a alternativa marcada."},{"p":"p2c","n":12,"t":"mc","tema":"inf","q":"Teniendo en cuenta los siguientes mediadores químicos y sus efectos correspondientes, marca la opción correcta:","o":["C5b-9 – opsonización","TNF – fiebre","Leucotrieno C4 – vasodilatación","Prostaciclina – aumento de la permeabilidad"],"ok":[1],"w":["C5b-9 é o complexo de ataque à membrana, que faz lise. Quem opsoniza é o C3b.","IL-1 e TNF são os pirógenos endógenos: induzem COX-2 e PGE2 no hipotálamo.","LTC4, D4 e E4 causam vasoconstrição, broncoespasmo e aumento de permeabilidade. Não são vasodilatadores.","Prostaciclina (PGI2) é vasodilatadora e antiagregante; o efeito principal não é permeabilidade."]},{"p":"p2c","n":13,"t":"cita","tema":"c7","q":"El término hialino corresponde a:","a":"Alteración en las células o en el espacio extracelular que da un aspecto homogéneo, vítreo y rosado en los cortes histológicos con H&E.","e":"É um termo descritivo, não uma substância. Intracelular: corpos de Russell, hialina de Mallory, gotas de reabsorção no túbulo proximal. Extracelular: arteriolosclerose hialina, amiloide, colágeno de cicatriz antiga."},{"p":"p2c","n":14,"t":"mc","tema":"inf","q":"En los siguientes pasos presentes en el reclutamiento de los leucocitos, ¿cuál de ellos se encuentra en orden secuencial?","o":["Transmigración, adhesión, fagocitosis","Marginación, adhesión, rodamiento","Rodamiento, adhesión, diapédesis","Migración, adhesión, transmigración"],"ok":[2],"w":["A adesão vem antes da transmigração.","O rolamento vem antes da adesão firme.","Ordem certa: marginação, rolamento (selectinas), adesão (integrinas), diapedese (PECAM-1) e quimiotaxia.","A migração no tecido é o último passo, não o primeiro."]},{"p":"p2c","n":15,"t":"mc","tema":"pig","q":"Con respecto a la neumoconiosis [antracosis] es correcto afirmar que (tiene dos respuestas correctas):","o":["Se observa en los pulmones de casi todos los adultos","Es más pronunciada en pacientes fumadores","No suele provocar ninguna reacción de lesión tisular","La exposición prolongada a partículas orgánicas e inorgánicas casi siempre se produce en lugar del tabaco"],"ok":[0,1],"w":["O carvão é poluente onipresente; a antracose aparece no pulmão de quase todo adulto urbano.","Fumantes acumulam mais pigmento.","Em geral é inócua, mas em grande quantidade induz reação fibroblástica e enfisema (pneumoconiose do mineiro). \"Ninguna reacción\" é absoluto demais.","Frase truncada na transcrição; como está, não tem sentido técnico."],"nt":"Transcrição confusa, misturando português. O tema real é antracose (pigmento exógeno); a dupla a + b é a mais defensável, mas não tenho a folha original."},{"p":"p2c","n":16,"t":"mc","tema":"inf","q":"Se realiza una toracocentesis de la cavidad pleural izquierda y se obtienen 500 ml de líquido. ¿Cuál de las siguientes características de este líquido indicaría con mayor probabilidad que se trata de un exudado?","o":["Alto contenido de proteínas","Aspecto claro, seroso","Recuento bajo de leucocitos","Baja densidad"],"ok":[0],"w":["Exsudato nasce do aumento de permeabilidade: proteína alta, densidade acima de 1,020, células e restos.","Claro e seroso sugere transudato.","Poucas células é transudato.","Densidade baixa (abaixo de 1,012) é transudato."]},{"p":"p2c","n":17,"t":"mc","tema":"inf","q":"Un grupo de pacientes recibe un inhibidor de la ciclooxigenasa 2 (COX-2). Los hombres adultos tenían insuficiencia cardíaca y artritis de pequeñas articulaciones. Refieren que el fármaco ha presentado ciertos efectos. ¿Cuál de los siguientes hallazgos es más probable que refiera el grupo que recibió el fármaco?","o":["Reducción del dolor articular","Numerosos episodios febriles","Mayor tumefacción de los tobillos"],"ok":[0],"w":["A COX-2 produz PGE2, que sensibiliza os nociceptores. Inibir a COX-2 reduz a dor.","A febre também depende de PGE2; o inibidor reduz a febre, não aumenta.","Retenção de sódio e edema podem ocorrer com coxibes, mas a questão (copiada do PEF, Q15) quer o efeito anti-inflamatório típico: menos dor."],"nt":"A transcrição cortou a 3ª alternativa; completei pelo Examen Final, que repete a mesma questão."},{"p":"p2c","n":18,"t":"mc","tema":"inf","q":"Una mujer de 58 años ha tenido tos con fiebre durante 3 días. Una radiografía de tórax revela infiltrados en el lóbulo inferior derecho. En un cultivo de esputo crece Streptococcus pneumoniae. La eliminación de estos organismos del parénquima pulmonar se lograría de manera más efectiva mediante la generación de ¿cuál de las siguientes sustancias por el principal tipo de célula inflamatoria que responde a esta infección?","o":["Prostaglandina E2","Calicreína","Leucotrieno B4","Peróxido de hidrógeno"],"ok":[3],"w":["PGE2 causa vasodilatação, dor e febre; não mata bactéria.","A calicreína gera bradicinina (dor e permeabilidade).","LTB4 é quimiotático: atrai o neutrófilo, mas não mata.","O neutrófilo (célula principal na pneumonia bacteriana) gera H2O2 pela NADPH oxidase, e a mieloperoxidase o converte em HOCl. O sistema H2O2-MPO-haleto é o bactericida mais eficiente."],"nt":"Copiada do Robbins (banco, Pregunta 4)."},{"p":"p2c","n":19,"t":"mc","tema":"inf","q":"Una niña de 4 años ha presentado numerosas infecciones por Staphylococcus aureus desde la lactancia. Las pruebas genéticas muestran un defecto causante de la ausencia de producción de β2-integrinas. ¿Cuál de las siguientes alteraciones es más probable que ocurra por deficiencia de β2-integrina?","o":["Menor producción de radicales libres (ERO)","Adhesión neutrofílica inadecuada al endotelio","Reducción de la fagocitosis de bacterias opsonizadas","Fracaso del proceso en el cual los leucocitos se colocan sobre el endotelio de forma transitoria"],"ok":[1],"w":["Os radicais vêm da NADPH oxidase; o defeito dela é a doença granulomatosa crônica.","As β2-integrinas (LFA-1 e Mac-1) fazem a adesão firme ao ICAM-1. É a deficiência de adesão leucocitária tipo 1.","Mac-1 também é receptor de iC3b, então a fagocitose cai um pouco, mas o defeito cobrado é a adesão.","Pousar no endotélio de forma transitória é o rolamento, feito pelas selectinas (deficiência de adesão tipo 2)."],"nt":"Repete na P2 da p. 97 (Q12) e no PEF (Q11)."},{"p":"p2c","n":20,"t":"mc","tema":"inf","q":"Un hombre de 37 años ha tenido náuseas y vómitos durante 5 semanas. Ayer experimentó un episodio de hematemesis. En el examen físico no presenta hallazgos anormales. Se realiza una endoscopia del tracto gastrointestinal superior y se observa una lesión de 1,5 cm de diámetro en el antro gástrico con pérdida de la superficie epitelial. ¿Estos hallazgos son más típicos de cuál de los siguientes procesos patológicos?","o":["Absceso","Granuloma","Gangrena","Úlcera"],"ok":[3],"w":["Abscesso é coleção de pus dentro do tecido, não perda de superfície.","Granuloma é agregado de macrófagos epitelioides (inflamação crônica).","Gangrena é necrose de um membro ou segmento.","Úlcera é a perda local do epitélio de superfície com tecido necrótico inflamado."],"nt":"Copiada do Robbins (banco, Pregunta 16)."},{"p":"p2d","n":1,"t":"cita","tema":"c7","q":"Cita dos patologías que cursan con depósitos de amiloide.","a":"Por ejemplo: mieloma múltiple (AL) y artritis reumatoide (AA). También valen Alzheimer (Aβ), amiloidosis senil (transtiretina), túnel carpiano por hemodiálisis (β2-microglobulina), carcinoma medular de tiroides (calcitonina), colitis ulcerosa/Crohn (AA).","e":"Duas armadilhas na lista do aluno. Parkinson não entra: não está na tabela de amiloidoses do Robbins (o depósito é α-sinucleína, corpos de Lewy). E o \"tumor de tiroides\" tem de ser o carcinoma MEDULAR; o papilar dá psamoma, não amiloide."},{"p":"p2d","n":2,"t":"cita","tema":"pig","q":"Cita pigmentos endógenos que no causan daño a la célula.","a":"Melanina y lipofuscina.","e":"A lipofuscina é o pigmento do desgaste (lipídio peroxidado): marca dano antigo por radicais livres, mas por si só não lesa a célula. A melanina é normal. Hemosiderina em excesso (hemocromatose) já causa dano."},{"p":"p2d","n":3,"t":"cita","tema":"inf","q":"Cite signos cardinales de inflamación resultantes de la vasodilatación.","a":"Rubor y calor.","e":"Mais sangue no local deixa vermelho e quente. Tumor vem do aumento de permeabilidade (edema), dor das prostaglandinas e da bradicinina."},{"p":"p2d","n":4,"t":"comp","tema":"c7","q":"Paciente masculino de 65 años consulta por palpitaciones. El ecocardiograma informa aurícula izquierda agrandada con área valvular mitral de 1 cm (reducida), en donde se constata calcificación de tipo ________.","a":"Distrófica.","e":"Válvula lesada com cálcio sérico normal é distrófica. Metastásica exigiria hipercalcemia e atinge tecidos normais (rim, pulmão, mucosa gástrica)."},{"p":"p2d","n":5,"t":"comp","tema":"inf","q":"La ________ es el principal mediador de las fases transitoria inmediata de la inflamación, causante de vasodilatación y aumento de permeabilidad vascular.","a":"Histamina.","e":"Está pré-formada nos grânulos do mastócito e sai em segundos. Age no receptor H1 das vênulas e contrai o endotélio: resposta transitória imediata, de 15 a 30 min."},{"p":"p2d","n":6,"t":"comp","tema":"c7","q":"Se denomina hialina de Mallory a la acumulación de ________ en células hepáticas relacionadas con el consumo de alcohol.","a":"Filamentos intermedios de queratina (citoqueratinas 8 y 18).","e":"Inclusões eosinófilas e ubiquitinadas no citoplasma do hepatócito (corpos de Mallory-Denk). Típicas da hepatite alcoólica, mas também aparecem em esteato-hepatite não alcoólica e Wilson."},{"p":"p2d","n":7,"t":"comp","tema":"inf","q":"En la inflamación aguda, la migración de leucocitos ocurre principalmente a través del endotelio de las ________.","a":"Vénulas poscapilares.","e":"É ali que a histamina age e que há mais selectinas e ICAM. Pegadinha das outras provas: \"vénulas precapilares\" não existe nesse contexto."},{"p":"p2d","n":8,"t":"cita","tema":"inf","q":"Moléculas de adhesión, expresadas en las células endoteliales, importantes para el proceso en el cual los leucocitos de forma individual y en filas se colocan sobre el endotelio de forma transitoria.","a":"E-selectina.","e":"Pousar de forma transitória é o rolamento, mediado por selectinas (E e P no endotélio). A \"familia de inmunoglobulinas\" (ICAM-1, VCAM-1) é da adesão firme. \"Marginación\" é o processo, não a molécula.","nt":"Seção com quadro de opções: Peroxidación de los lípidos de la membrana · Metabolitos del ácido araquidónico · Desoxihemoglobina · Familia de inmunoglobulinas · Complejo de ataque a membrana · E-selectina · Sistema del complemento · Productos de degradación de hemoglobina · Marginación."},{"p":"p2d","n":9,"t":"cita","tema":"inf","q":"Las bacterias son fagocitadas por neutrófilos o sufren lisis, efectos que son facilitados por componentes del plasma sanguíneo:","a":"Sistema del complemento.","e":"A pergunta junta fagocitose (opsonização por C3b) e lise (C5b-9). O componente que faz as duas coisas é o sistema do complemento.","nt":"O aluno respondeu \"Complejo de ataque de membrana\", que só cobre a lise. O Examen Final (Q10) e o PEF (Q19) dão \"complemento\"."},{"p":"p2d","n":10,"t":"cita","tema":"pig","q":"Una mujer de 22 años tiene anemia congénita y ha recibido transfusiones durante muchos años. Ahora tiene un color bronce más oscuro en la piel por depósito de sustancias:","a":"Productos de degradación de la hemoglobina (hemosiderina).","e":"Transfusões repetidas mais hemólise sobrecarregam de ferro: hemossiderose sistêmica, hemocromatose secundária. A desoxi-hemoglobina dá cianose, não depósito."},{"p":"p2d","n":11,"t":"mc","tema":"c7","q":"¿Cuál de las siguientes alteraciones es posible encontrar en los cuerpos de psamoma?","o":["Ateromas de aterosclerosis avanzada","Válvulas cardíacas de ancianos","Ganglios linfáticos tuberculosos","Carcinoma papilar de tiroides"],"ok":[3],"w":["O ateroma avançado tem calcificação distrófica, mas amorfa, sem lâminas concêntricas.","Válvula senil tem calcificação distrófica grosseira, sem psamoma.","Linfonodo tuberculoso calcifica sobre a necrose caseosa, sem psamoma.","Psamoma é calcificação distrófica lamelar em papilas: carcinoma papilar de tireoide, cistoadenocarcinoma seroso de ovário, meningioma."],"nt":"As quatro são calcificação distrófica; só a d forma psamoma."},{"p":"p2d","n":12,"t":"mc","tema":"inf","q":"La pericarditis en \"pan con mantequilla\" es un ejemplo típico de inflamación de tipo:","o":["Serosa","Fibrinosa","Supurativa","Ulcerativa"],"ok":[1],"w":["Serosa é líquido pobre em proteína e células (bolha, derrame).","Fibrina depositada entre os folhetos: ao separá-los parece pão com manteiga. Típica de febre reumática, uremia e pós-infarto.","Supurativa é pus: neutrófilos e necrose liquefativa.","Ulcerativa é perda de epitélio de superfície, não exsudato em serosa."]},{"p":"p2d","n":13,"t":"mc","tema":"inf","q":"Teniendo en cuenta los siguientes mediadores químicos y sus efectos correspondientes, marca la alternativa correcta:","o":["Leucotrieno B4 – vasodilatación","Interleucina 6 – dolor","C3b – opsonización","Prostaciclina – aumento de la permeabilidad"],"ok":[2],"w":["LTB4 é quimiotático e ativa neutrófilos.","IL-6 dá febre e proteínas de fase aguda (PCR). Dor é prostaglandinas e bradicinina.","O C3b recobre o micróbio e é reconhecido pelo receptor CR1 do fagócito.","Prostaciclina é vasodilatadora e antiagregante."]},{"p":"p2d","n":14,"t":"mc","tema":"c7","q":"Con respecto al depósito de material amiloide es correcto afirmar que:","o":["La tinción usada comúnmente para su visualización es rojo Congo","Las sustancias insolubles se depositan en el citoplasma de las células","La amiloidosis […] es la forma más frecuente de la amiloidosis senil","En la amiloidosis secundaria se acumulan amiloides de cadena ligera de las células plasmáticas"],"ok":[0],"w":["Vermelho Congo é a coloração de rotina para amiloide.","Amiloide é sempre EXTRACELULAR, entre as células e em volta dos vasos.","Palavra cortada na transcrição. A amiloidose senil sistêmica é de transtirretina normal e atinge sobretudo o coração; se a alternativa trazia outro tipo, estava errada. A resposta segura é a a.","Cadeia leve (AL) é a amiloidose primária, de plasmócitos. A secundária (reativa) é AA, vinda da SAA do fígado na inflamação crônica."]},{"p":"p2d","n":15,"t":"mc","tema":"pig","q":"Analiza los siguientes enunciados sobre acumulación intracelular de pigmentos. 1. Para confirmar los depósitos de hemosiderina se utiliza la tinción azul de Prusia. 2. Las células de insuficiencia cardíaca corresponden a macrófagos alveolares cargados de biliverdina. 3. El pigmento de lipocromo es un indicador de lesión por radicales libres y peroxidación lipídica. 4. La antracosis se produce por exposición prolongada a sustancias inhaladas, como el carbón, e induce una reacción fibroblástica en los pulmones. De estas, ¿cuáles corresponden a respuestas correctas?","o":["1 y 3","1 y 4","2 y 3","3 y 4"],"ok":[0],"w":["1 é verdadeira (azul da Prússia ou Perls cora ferro). 3 é verdadeira (lipocromo é a lipofuscina, marcador de peroxidação lipídica).","A 4 generaliza: a antracose comum é inócua; reação fibroblástica só com grande acúmulo (pneumoconiose do mineiro).","A 2 é falsa: as células da insuficiência cardíaca têm hemosiderina, não biliverdina.","A 4 é a frase que generaliza (ver b)."]},{"p":"p2d","n":16,"t":"mc","tema":"c7","q":"Los cuerpos de Russell en las células plasmáticas del bazo de un hombre de 60 años están llenos de:","o":["Transtiretina","AAT (α1-antitripsina)","Inmunoglobulina","β2-microglobulina"],"ok":[2],"w":["Transtirretina é a amiloidose senil e a familiar.","A AAT forma glóbulos no hepatócito, não no plasmócito.","Corpos de Russell são imunoglobulina recém-sintetizada acumulada no retículo endoplasmático rugoso do plasmócito: inclusões redondas, homogêneas e eosinófilas.","β2-microglobulina é o amiloide da hemodiálise."]},{"p":"p2d","n":17,"t":"mc","tema":"inf","q":"En la toracocentesis realizada en la cavidad pleural izquierda se obtiene un líquido amarillento y turbio que tiene un recuento de leucocitos aumentado con predominio de neutrófilos. La tinción de Gram muestra cocos Gram +. ¿Cuál de los siguientes términos describe el proceso?","o":["Exudado fibrinoso","Ultrafiltrado de plasma","Organización y cicatrización","Exudado purulento"],"ok":[3],"w":["Fibrinoso é fibrina sobre a serosa, sem pus.","Ultrafiltrado de plasma é transudato: claro e pobre em células.","Organização é a fase de reparo (tecido de granulação, fibrose).","Turvo, cheio de neutrófilos e com cocos piogênicos é pus; na pleura se chama empiema."],"nt":"Copiada do PEF (Q23)."},{"p":"p2d","n":18,"t":"mc","tema":"inf","q":"Hombre de 25 años presenta disnea progresiva en las últimas horas; mediante una toracocentesis se obtienen 200 ml de un líquido amarillo ligeramente turbio en la cavidad pleural derecha. El examen citológico del líquido revela múltiples neutrófilos. ¿Cuál de los siguientes mecanismos contribuye a la acumulación de este líquido pleural?","o":["Vasoconstricción arteriolar","Contracción endotelial","Obstrucción linfática","Liberación de los lisosomas por los neutrófilos"],"ok":[1],"w":["A vasoconstrição é transitória e reduz o fluxo; não forma exsudato.","Mecanismo mais comum do aumento de permeabilidade: histamina, bradicinina e LTs contraem o endotélio das vênulas e abrem fendas.","Obstrução linfática dá linfedema; aqui há neutrófilos, então é exsudato inflamatório.","Enzimas lisossômicas lesam o tecido, mas não são o mecanismo principal do acúmulo de líquido."],"nt":"Copiada do PEF (Q5)."},{"p":"p2d","n":19,"t":"mc","tema":"inf","q":"Hombre de 22 años desarrolla dolor abdominal marcado en el cuadrante inferior derecho. Se realiza una cirugía laparoscópica y el apéndice está hinchado, eritematoso, parcialmente cubierto por exudado amarillento. ¿Cuál de los siguientes mediadores químicos es causante del dolor que experimenta el paciente?","o":["Complemento C3b e inmunoglobulina G","IL-1 y TNF","Prostaglandinas y bradicinina","Leucotrienos y HPETE"],"ok":[2],"w":["C3b e IgG são opsoninas.","IL-1 e TNF dão febre e resposta de fase aguda.","A PGE2 sensibiliza as terminações nervosas à bradicinina: dor.","Leucotrienos dão broncoespasmo, permeabilidade e quimiotaxia; HPETE é intermediário da lipoxigenase."],"nt":"Copiada do Robbins (banco, Pregunta 1)."},{"p":"p2d","n":20,"t":"mc","tema":"c7","q":"Paciente masculino de 65 años, conocido portador de enfermedad renal crónica, con diálisis 3 veces por semana, acude a la consulta por dolor en la mano izquierda. Se evidencian depósitos de calcio en las articulaciones carpometacarpianas. En la prueba de laboratorio muestra una calcemia de 15,4 (valores normales […]).","o":["Calcificación metastásica","Calcificación idiopática","Calcificación distrófica","Calcificación senil"],"ok":[0],"w":["Hipercalcemia (renal crônico: hiperparatireoidismo secundário e retenção de fosfato) com cálcio em tecido normal é metastásica.","\"Idiopática\" não é categoria de calcificação patológica no Robbins.","Distrófica ocorre com cálcio normal, em tecido morto ou lesado.","\"Senil\" não é categoria; a calcificação valvar do idoso é distrófica."]},{"p":"reg24","n":1,"t":"cita","tema":"c7","q":"2 patologías que presentan una amiloidosis sistémica reactiva (secundaria):","a":"Artritis reumatoide y enfermedad de Crohn o colitis ulcerosa (también tuberculosis, bronquiectasias, osteomielitis crónica).","e":"Reativa é a AA: inflamação crônica, IL-6 e IL-1, SAA produzida pelo fígado. O aluno respondeu Crohn e colite ulcerosa, ambas certas. Mieloma não serve: é AL, primária."},{"p":"reg24","n":2,"t":"cita","tema":"inf","q":"2 mediadores químicos que causan aumento de la permeabilidad vascular:","a":"Histamina y bradicinina (también LTC4, LTD4, LTE4).","e":"Resposta do aluno correta. C3a e C5a aumentam a permeabilidade indiretamente, liberando histamina."},{"p":"reg24","n":3,"t":"cita","tema":"inf","q":"2 fagocitos principales presentes en la reacción inflamatoria aguda:","a":"Neutrófilos y macrófagos.","e":"O aluno riscou \"mastocitos\" e fez bem: mastócito não é fagócito, ele libera histamina."},{"p":"reg24","n":4,"t":"comp","tema":"c7","q":"Paciente masculino de 65 años consulta por palpitaciones, el ecocardiograma informa aurícula izquierda agrandada con área valvular mitral de 1 cm (reducida), en donde se constata calcificación de tipo ________.","a":"Distrófica.","e":"Mesma questão da P2 Turma D (Q4): válvula lesada e cálcio normal."},{"p":"reg24","n":5,"t":"comp","tema":"inf","q":"La ________ es el principal mediador de la fase transitoria inmediata de la inflamación, causante de dilatación arteriolar y aumento de permeabilidad venular.","a":"Histamina.","e":"Repetida da Turma D (Q5)."},{"p":"reg24","n":6,"t":"comp","tema":"c7","q":"Los cuerpos de Russell en las células plasmáticas del bazo de un hombre de 60 años están cargados de ________.","a":"Inmunoglobulinas.","e":"Na Turma D a mesma pergunta veio de múltipla escolha (Q16)."},{"p":"reg24","n":7,"t":"comp","tema":"inf","q":"La pericarditis \"en pan con mantequilla\" es un ejemplo típico de inflamación aguda tipo ________.","a":"Fibrinosa.","e":"Caiu nas três provas de P2 que temos."},{"p":"rec23","n":1,"t":"mc","tema":"inf","q":"Paciente femenina de 25 años de edad que, cocinando los alimentos en su casa, sufre quemaduras de la mano con presencia posteriormente de ampollas a ese nivel. ¿Qué tipo de inflamación presentaría y cuál sería la característica de la extravasación?","o":["Inflamación serosa; líquido con bajo contenido de células","Inflamación fibrinosa; líquido con red eosinófila de fibrina","Absceso; líquido con alto contenido de neutrófilos","Inflamación supurativa; líquido con elevada concentración de proteínas"],"ok":[0],"w":["Bolha de queimadura é inflamação serosa: líquido pobre em células, vindo do plasma.","Fibrinosa exige permeabilidade maior e aparece em cavidades (pericárdio, pleura), não em bolha.","Abscesso é pus localizado por infecção piogênica.","Supurativa é pus. A proteína alta é de qualquer exsudato; o que define o pus são neutrófilos e necrose."]},{"p":"rec23","n":2,"t":"mc","tema":"inf","q":"Paciente de 20 años de edad que hace 2 días presenta fiebre elevada, dolor en fosas lumbares y ardor al orinar; en el examen de orina se encuentran leucocitos abundantes. En la respuesta inflamatoria, de los siguientes procesos, ¿cuál se produce más tardíamente?","o":["Liberación de histamina por degranulación de mastocitos","Vasodilatación y estasis sanguínea","Migración de monocitos","Extravasación de líquido al espacio intersticial"],"ok":[2],"w":["A histamina sai em segundos: é o primeiro evento.","Vasodilatação e estase acontecem em minutos a poucas horas.","Neutrófilos predominam nas primeiras 6 a 24 h; monócitos e macrófagos os substituem entre 24 e 48 h.","A exsudação vem cedo, junto com o aumento de permeabilidade."]},{"p":"rec23","n":3,"t":"mc","tema":"inf","q":"Paciente de 18 años de edad, femenina, con el antecedente de padecer una fiebre reumática y que ahora presenta fiebre, soplo cardíaco y un roce pericárdico; se le diagnostica una pericarditis \"en pan y manteca\", que es un ejemplo típico de inflamación de tipo:","o":["Serosa","Fibrinosa","Supurativa","Ulcerativa"],"ok":[1],"w":["Serosa é líquido pobre em células e proteína.","Fibrina entre os folhetos do pericárdio, como pão com manteiga. Febre reumática é causa clássica.","Supurativa é pus.","Ulcerativa é perda de epitélio de superfície."]},{"p":"rec23","n":4,"t":"mc","tema":"inf","q":"Paciente de 38 años de edad, masculino, fumador, presenta dolor en epigastrio y acidez. Se le realiza una gastroscopia y se observa lesión ulcerada en el antro gástrico. ¿Qué mediadores químicos estarían implicados en la producción del dolor?","o":["Anafilotoxinas","Leucotrieno B4","Opsoninas","Bradicinina"],"ok":[3],"w":["C3a e C5a liberam histamina (permeabilidade); C5a também atrai leucócitos.","LTB4 é quimiotático.","Opsoninas (C3b, IgG) facilitam a fagocitose.","Bradicinina, junto com a PGE2, estimula as terminações nervosas da dor."]},{"p":"rec23","n":5,"t":"mc","tema":"cro","q":"Se pueden observar células gigantes multinucleadas en todos los siguientes procesos inflamatorios, excepto:","o":["Tuberculosis","Sarcoidosis","Leishmaniasis","Cuerpos extraños"],"ok":[2],"w":["tuberculosis tem granuloma caseoso com células de Langhans. O aluno marcou esta, e errou.","Sarcoidose tem granuloma não caseoso com células gigantes.","É a única fora da lista de doenças granulomatosas do Robbins; o achado típico são macrófagos cheios de amastigotas. Ressalva: formas crônicas podem formar granuloma, então é a \"menos típica\", não um \"nunca\".","Corpo estranho tem células gigantes do tipo corpo estranho em volta do material."],"nt":"Inflamação crônica e granulomatosa, fora dos slides da P2 atual. Gabarito com ressalva."},{"p":"rec23","n":6,"t":"mc","tema":"inf","q":"Paciente femenina de 40 años de edad que, con antecedentes de una sinusitis aguda mal tratada, hace un absceso cerebral como complicación. En la complicación inflamatoria observada generalmente no se observará:","o":["Vasodilatación y vasocongestión","Presencia de leucotrieno B4","Infiltrado linfoplasmocitario","Residuos licuados de células necróticas"],"ok":[2],"w":["Abscesso é inflamação aguda: há vasodilatação e congestão.","LTB4 atrai neutrófilos, então está presente. O aluno marcou esta, e errou.","Linfócitos e plasmócitos são da inflamação crônica; no abscesso agudo predominam neutrófilos.","Abscesso é necrose liquefativa: os restos liquefeitos estão lá."]},{"p":"rec23","n":7,"t":"vf","tema":"inf","q":"La inhibición selectiva de la vía de la ciclooxigenasa en el metabolismo del ácido araquidónico influirá negativamente en la formación de leucotrienos y prostaglandinas.","ok":false,"e":"A COX produz prostaglandinas e tromboxano. Leucotrienos vêm da 5-lipoxigenase, então inibir a COX não os reduz (pode até desviar substrato para eles, como na asma por aspirina)."},{"p":"rec23","n":8,"t":"vf","tema":"inf","q":"El fenómeno de migración es un proceso de redistribución leucocitaria, por el cual los leucocitos se sitúan en la periferia del flujo sanguíneo.","ok":false,"e":"Isso é marginação. Migração (transmigração) é atravessar o endotélio."},{"p":"rec23","n":9,"t":"vf","tema":"inf","q":"La forma en que inicialmente aumenta la permeabilidad vascular es por la contracción de células endoteliales, que determinan el incremento de los espacios interendoteliales.","ok":true,"e":"É o mecanismo mais comum e mais precoce: histamina, bradicinina e leucotrienos, nas vênulas pós-capilares, durando 15 a 30 min."},{"p":"rec23","n":10,"t":"vf","tema":"inf","q":"Cuando la sangre circula por el lecho capilar, se puede distinguir un flujo central y un flujo periférico. En condiciones normales, el flujo central contiene leucocitos y eritrocitos.","ok":true,"e":"No fluxo laminar normal as células ficam na coluna axial e o plasma na periferia. Com a estase os leucócitos vão para a periferia (marginação)."},{"p":"rec23","n":11,"t":"cita","tema":"inf","q":"3 manifestaciones locales de inflamación conocidas como signos cardinales:","a":"Rubor, calor y tumor (también dolor y pérdida de función).","e":"Celso descreveu rubor, tumor, calor e dor; Virchow acrescentou a functio laesa."},{"p":"rec23","n":12,"t":"cita","tema":"inf","q":"2 mediadores químicos de inflamación derivados del plasma:","a":"Complemento (anafilotoxinas C3a y C5a) y cininas (bradicinina). También el sistema de coagulación (trombina).","e":"Os plasmáticos circulam como precursores inativos feitos no fígado. Histamina, prostaglandinas, leucotrienos e citocinas são de origem celular."},{"p":"rec23","n":13,"t":"comp","tema":"cro","q":"Las células gigantes multinucleadas derivan de la activación de ________.","a":"Macrófagos.","e":"Fusão de macrófagos ativados por IFN-γ, no granuloma.","nt":"Inflamação crônica e granulomas: slide da Clase 10 (inflamación crónica)."},{"p":"rec23","n":14,"t":"comp","tema":"inf","q":"El principal mediador en el edema producido por una reacción alérgica aguda es ________.","a":"Histamina.","e":"O aluno escreveu \"mastocitos\": é a célula, não o mediador. Erro clássico que tira o ponto."},{"p":"rec23","n":15,"t":"comp","tema":"cro","q":"La presencia de ________ son condiciones para la formación de un granuloma.","a":"Un agente difícil de erradicar (persistente) y una respuesta inmune mediada por linfocitos T.","e":"O granuloma tenta conter um agente que não se elimina (micobactéria, fungo, corpo estranho) e é mantido por Th1 e IFN-γ.","nt":"Inflamação crônica e granulomas: slide da Clase 10 (inflamación crónica)."},{"p":"p2f1","n":9,"t":"mc","tema":"pig","q":"Con respecto a la antracosis es correcto afirmar que:","o":["Están relacionadas a enfermedades pulmonares ocupacionales","Puede inducir una reacción fibroblástica en los pulmones","Se debe a la inhalación de sustancias orgánicas e inorgánicas como la sílice y el carbón","El polvo de carbón es captado por macrófagos alveolares y transportado en ganglios linfáticos traqueobronquiales"],"ok":[3],"w":["A antracose em si é achado comum e inócuo de quem vive na cidade; doença ocupacional é a pneumoconiose do mineiro, a forma grave.","Só é verdade com grande acúmulo (pneumoconiose). Como afirmação sobre a antracose em geral, fica incompleta.","Antracose é só carvão. Sílica causa silicose.","É a descrição do Robbins: macrófagos alveolares captam o carvão e o levam aos linfonodos traqueobrônquicos, que ficam pretos."],"nt":"A b aparece como afirmação na Turma D (Q15, item 4). A d é a única sem ressalva."},{"p":"p2f1","n":10,"t":"mc","tema":"inf","q":"¿Cuál de los siguientes procesos se presenta más tempranamente en la inflamación aguda?","o":["Adhesión neutrofílica","Incremento de la permeabilidad vascular","Formación de edema inflamatorio","Destrucción tisular"],"ok":[1],"w":["A adesão vem depois das alterações vasculares e da ativação do endotélio.","As alterações vasculares (vasodilatação e aumento de permeabilidade) são o primeiro evento; das opções, é a mais precoce.","O edema é consequência do aumento de permeabilidade.","A destruição do tecido por enzimas e radicais é tardia."]},{"p":"p2f1","n":11,"t":"mc","tema":"inf","q":"Se realiza una toracocentesis de la cavidad pleural izquierda y se obtienen 500 ml de líquido. ¿Cuál de las siguientes características de este líquido indicaría con mayor probabilidad que se trata de un exudado?","o":["Alto contenido de proteínas","Aspecto claro, seroso","Recuento bajo de leucocitos","Baja densidad"],"ok":[0],"w":["Proteína alta é a marca do exsudato.","Claro e seroso é transudato.","Poucas células é transudato.","Densidade baixa é transudato."],"nt":"Mesma questão da P2 Turma C (Q16)."},{"p":"p2f1","n":12,"t":"mc","tema":"inf","q":"Una niña de 4 años ha presentado numerosas infecciones por Staphylococcus aureus desde la lactancia. Las pruebas genéticas muestran un defecto causante de la ausencia de producción de β2-integrina. ¿Cuál de las siguientes alteraciones es más probable que ocurra por deficiencia de β2-integrina?","o":["Menor producción de radicales libres (ERO)","Adhesión neutrofílica inadecuada al endotelio","Reducción de la fagocitosis de bacterias opsonizadas","Fracaso del proceso en el cual los leucocitos se colocan sobre el endotelio de forma transitoria"],"ok":[1],"w":["Radicais dependem da NADPH oxidase.","β2-integrinas fazem a adesão firme: deficiência de adesão leucocitária tipo 1.","Efeito secundário (Mac-1 é receptor de iC3b); não é o principal.","Isso é rolamento, feito pelas selectinas."],"nt":"Mesma questão da P2 Turma C (Q19)."},{"p":"p2f1","n":13,"t":"mc","tema":"nec","q":"Mujer de 29 años con una comunicación interventricular lleva 3 semanas con fiebre persistente de 38,6 °C y cefalea. Una TAC craneal muestra una lesión en anillo de 3 cm, de contenido licuado, que capta contraste en el lóbulo parietal derecho del encéfalo. ¿Cuál de las siguientes acciones de las células inflamatorias es más probable que haya producido este hallazgo en la TAC?","o":["Elaboración de óxido nítrico por los macrófagos","Formación de inmunoglobulinas por linfocitos B","Liberación de enzimas lisosómicas por los neutrófilos","Producción de interferón γ por linfocitos T"],"ok":[2],"w":["O NO dos macrófagos mata micróbios e dilata vasos, mas não liquefaz tecido.","Imunoglobulinas opsonizam; não causam necrose.","Abscesso cerebral (endocardite com CIV, êmbolo séptico): as enzimas dos neutrófilos digerem o tecido e formam necrose liquefativa, a cavidade com conteúdo líquido.","IFN-γ ativa macrófagos: granuloma, inflamação crônica."],"nt":"Copiada do PEF (Q27)."},{"p":"p2f1","n":14,"t":"mc","tema":"inf","q":"Paciente femenina de 53 años sufre dolor abdominal de 2 semanas de evolución. No tiene fiebre; la zona superior del abdomen es ligeramente dolorosa, y se conservan los ruidos intestinales. Se realiza una biopsia y se observa una lesión duodenal caracterizada por pérdida local de la superficie mucosa que contiene restos necróticos inflamados. ¿Cuál de los siguientes procesos patológicos es más probable que esté presente?","o":["Úlceras","Absceso","Inflamación crónica","Exudado purulento"],"ok":[0],"w":["Perda local da superfície mucosa com restos necróticos inflamados é a definição de úlcera.","Abscesso é coleção de pus dentro do tecido.","O aluno marcou esta, e errou. A base de uma úlcera antiga tem inflamação crônica, mas a lesão descrita se chama úlcera.","Exsudato purulento é líquido, não perda de superfície."],"nt":"Copiada do PEF (Q25)."},{"p":"p2f2","n":1,"t":"cita","tema":"c7","q":"2 tipos de calcificación patológica:","a":"Distrófica y metastásica.","e":"Distrófica: tecido morto ou lesado, cálcio sérico normal. Metastásica: tecido normal, hipercalcemia."},{"p":"p2f2","n":2,"t":"cita","tema":"inf","q":"2 pasos del reclutamiento de leucocitos ocurridos en la luz vascular:","a":"Marginación y rodamiento (también adhesión).","e":"Na luz: marginação, rolamento e adesão. No tecido: transmigração e quimiotaxia (o Examen Final pergunta essa outra metade)."},{"p":"p2f2","n":3,"t":"cita","tema":"c7","q":"Mujer sana de 73 años cae por las escaleras y se lesiona la cadera derecha. No hay fractura, pero la radiografía revela calcificación de las pequeñas arterias musculares laterales al útero.","a":"Esclerosis medial calcificada.","e":"Idosa saudável, sem hipercalcemia, cálcio na média de artérias musculares: Mönckeberg.","nt":"O aluno escreveu \"calcificación metastásica\" e errou. Seção com quadro de opções: Hemosiderina · Trasudado · Calcificación metaplásica · Aterosclerosis ulcerosa · Bilirrubina · Esclerosis medial calcificada · Exudado purulento · Lipofuscina · Cuerpos de psamoma."},{"p":"p2f2","n":4,"t":"cita","tema":"pig","q":"Hombre de 35 años es golpeado en la pierna por un estante que cayó. La piel no está rota; 16 días después presenta una lesión de color amarillo-marrón producida por acumulación de una sustancia:","a":"Hemosiderina.","e":"O hematoma muda de cor: vermelho-azulado (Hb), verde-azulado (biliverdina), amarelo (bilirrubina) e por fim marrom-dourado (hemosiderina). Depois de duas semanas o que sobra é hemosiderina. Bilirrubina está no quadro como pegadinha."},{"p":"p2f2","n":5,"t":"cita","tema":"inf","q":"Hombre de 25 años lleva todo el día trabajando en su jardín. En el examen físico se observa una ampolla por fricción en la piel de las manos.","a":"Trasudado.","e":"No Robbins a resposta é \"inflamação serosa\". Como o quadro não tem \"serosa\", o termo que sobra para líquido pobre em proteína e células é trasudado. Exsudato purulento exigiria infecção.","nt":"Gabarito com ressalva: depende do quadro de opções."},{"p":"p2f2","n":6,"t":"comp","tema":"pig","q":"Las llamadas \"células de la insuficiencia cardíaca\" corresponden a acúmulos de pigmento de ________ dentro de ________.","a":"Hemosiderina; macrófagos alveolares.","e":"Congestão pulmonar crônica: hemácias no alvéolo, Hb degradada pelos macrófagos, ferro guardado como hemosiderina."},{"p":"p2f2","n":7,"t":"comp","tema":"pig","q":"Para confirmar el depósito de pigmento hemosiderínico en un paciente con anemia hemolítica se utiliza la tinción ________.","a":"Azul de Prusia (Perls).","e":"O ferro férrico reage com o ferrocianeto e fica azul. A bilirrubina não cora com Perls."},{"p":"p2f2","n":8,"t":"mc","tema":"c7","q":"¿Cuál de los siguientes enunciados corresponde a la calcificación distrófica?","o":["Es altamente sugestiva de una enfermedad renal crónica","Se observa en pacientes con hiperparatiroidismo primario","Puede observarse en placas ateromatosas complicadas","Es frecuente en la intoxicación por vitamina D"],"ok":[2],"w":["Renal crônica leva a hiperparatireoidismo secundário: metastásica.","Hiperparatireoidismo primário dá hipercalcemia: metastásica.","Ateroma avançado é tecido lesado com cálcio normal: distrófica (a aorta fica como casca de ovo).","Intoxicação por vitamina D dá hipercalcemia: metastásica."]},{"p":"par1","n":1,"t":"cita","tema":"apo","q":"Dos enzimas involucradas en el proceso de muerte por apoptosis.","a":"Caspasas y endonucleasas.","e":"Na correção o citocromo c foi anulado: não é enzima. Ele é uma proteína da cadeia respiratória que, no citosol, forma o apoptossomo com Apaf-1."},{"p":"par1","n":2,"t":"cita","tema":"nec","q":"Patrones de necrosis que presentan digestión enzimática.","a":"Necrosis licuefactiva y necrosis grasa.","e":"Digestão enzimática: liquefativa, gordurosa (lipases pancreáticas) e a gangrena úmida. Desnaturação de proteínas: coagulativa e gangrena seca. A caseosa é mistura e não é a resposta esperada."},{"p":"par1","n":3,"t":"cita","tema":"acu","q":"Dos componentes principales de las placas arterioscleróticas.","a":"Células (macrófagos/células espumosas, células musculares lisas, linfocitos T), matriz extracelular (colágeno, cápsula fibrosa) y lípidos (colesterol y ésteres de colesterol).","e":"O Robbins resume em três componentes: células, matriz extracelular e lipídios. Quaisquer dois valem."},{"p":"par1","n":4,"t":"comp","tema":"nec","q":"Picnosis es un cambio nuclear caracterizado por ________ nuclear y aumento de basofilia (la cromatina se condensa en una masa basófila sólida).","a":"Retracción (encogimiento).","e":"Picnose: núcleo pequeno, denso e hipercromático. Cariorrexe: fragmenta. Cariólise: perde a basofilia pela ação das DNases."},{"p":"par1","n":6,"t":"comp","tema":"acu","q":"La tinción ________ da una coloración azul negra a depósitos intracelulares excesivos de triglicéridos.","a":"Sudán negro B.","e":"Lipídios exigem corte por congelação, porque o álcool do processamento os dissolve. Sudão IV e Oil Red O coram de vermelho-alaranjado; Sudão negro B, de azul-negro. No H&E ficam só vacúolos vazios."},{"p":"par1","n":9,"t":"cita","tema":"apo","q":"La muerte causada por el aumento de la permeabilidad de la membrana mitocondrial externa, que permite la activación de sustancias citosólicas…","a":"Caspasas iniciadoras.","e":"Via intrínseca: BAX e BAK abrem a membrana externa, sai o citocromo c, que com Apaf-1 forma o apoptossomo e ativa a caspase 9, a iniciadora.","nt":"Seção com quadro de opções: Falla de bomba Na⁺/K⁺ · Lipasas pancreáticas activas · Síntesis de proteínas disminuidas · Necroptosis · Presencia de espacios quísticos · Colesterol LDL (lipoproteína de baja densidad) bajo · Gangrena seca · Aumento de la mitosis celular · Caspasas iniciadoras. Na P1 Turma C a mesma ideia tinha como resposta \"presencia de citocromo c\"."},{"p":"par1","n":10,"t":"cita","tema":"nec","q":"Mujer de 75 años sufrió pérdida de conocimiento. No puede hablar ni mover el brazo derecho a causa de una oclusión de la arteria cerebral media izquierda.","a":"Presencia de espacios quísticos.","e":"Infarto cerebral é necrose liquefativa (tecido rico em lipídios e pobre em estroma). Com o tempo vira uma cavidade cística."},{"p":"par1","n":12,"t":"mc","tema":"nec","q":"Al microscopio óptico, en un patrón de lesión celular irreversible, se podrá observar de forma característica:","o":["Vacuolas lipídicas transparentes en el citoplasma de las células","Presencia de masas de fosfolípidos llamadas figuras de mielina","Formación de vesículas en las membranas plasmáticas","Aumento de la acidofilia por medio de ARN citoplasmático"],"ok":[1],"w":["Vacúolos lipídicos (alteração gordurosa) são lesão reversível.","Frase do slide: na necrose as células podem ser substituídas por grandes massas de fosfolipídios, as figuras de mielina.","Bolhas na membrana são lesão reversível.","A eosinofilia aumenta pela PERDA do RNA (que fixa a hematoxilina) e pelas proteínas desnaturadas. \"Por meio de RNA\" inverte o mecanismo."]},{"p":"par1","n":14,"t":"mc","tema":"apo","q":"¿Qué trastorno clínico se asocia con una apoptosis fisiológica?","o":["Infección en el pie derecho en un paciente diabético","Paciente con demencia por enfermedad de Parkinson","Verrugas cutáneas en pacientes con infección por papilomavirus","Eliminación de las membranas interdigitales para la formación de los dedos"],"ok":[3],"w":["Pé diabético infectado é gangrena (necrose).","Neurodegeneração é apoptose PATOLÓGICA (proteínas mal dobradas).","O virus del papiloma humano inibe a apoptose (a E6 degrada a p53); a verruga é proliferação.","Embriogênese é o exemplo clássico de apoptose fisiológica."]},{"p":"par1","n":15,"t":"mc","tema":"acu","q":"¿Cuál de los siguientes corresponde a una complicación de las placas ateromatosas?","o":["Taponamiento","Rotura del músculo papilar","Hemorragia pericárdica","Formación de aneurismas"],"ok":[3],"w":["Tamponamento é complicação do INFARTO (ruptura da parede livre), não da placa.","Ruptura de músculo papilar também é complicação do infarto.","Hemopericárdio vem da ruptura cardíaca pós-infarto.","A placa atrofia a média e enfraquece a parede: aneurisma (aorta abdominal). Outras: ruptura, hemorragia intraplaca, trombose, ateroembolia e calcificação."]},{"p":"par1","n":16,"t":"mc","tema":"acu","q":"¿Cuál de las siguientes coloraciones sería la preferible para evidenciar adecuadamente la presencia de acumulaciones intracelulares en la glucogenosis tipo IV?","o":["Hematoxilina y eosina","Tricrómica de Mallory","Ácido peryódico de Schiff","Aceite rojo O"],"ok":[2],"w":["No H&E o glicogênio aparece só como vacúolo claro.","Tricrômico cora colágeno.","PAS (ácido periódico de Schiff) cora glicogênio de magenta (confirma com diastase). Carmim de Best também serve.","Oil Red O é para lipídios."]},{"p":"par1","n":19,"t":"mc","tema":"nec","q":"Hombre de 55 años que tiene DM mal controlada hace 15 años presentó una extensa coloración negra de la piel y tejidos blandos del pie derecho con áreas de exudado amarillento. Se cultiva Staphylococcus aureus y se realiza la amputación. ¿Cuál de las siguientes anomalías patológicas tiene más probabilidad de mostrar la muestra recibida en el laboratorio?","o":["Apoptosis patológica","Infarto rojo","Gangrena húmeda","Necrosis caseosa"],"ok":[2],"w":["Apoptose não deixa o membro preto nem gera exsudato.","Infarto vermelho é de órgão com dupla circulação (pulmão, intestino).","Isquemia (coagulativa) com infecção bacteriana sobreposta (liquefativa) e exsudato: gangrena úmida.","Caseosa é da tuberculose."]},{"p":"p1c","n":1,"t":"cita","tema":"acu","q":"Dos rasgos macroscópicos presentes en el hígado con esteatosis:","a":"Hígado aumentado de tamaño y peso, amarillo, blando y grasoso, con cápsula tensa y brillante y bordes redondeados.","e":"Use os termos do slide. A resposta anotada pelo aluno (\"bordes regulares, cápsula densa\") não confere."},{"p":"p1c","n":2,"t":"cita","tema":"nec","q":"Dos patrones de necrosis que presentan primariamente desnaturalización de proteínas:","a":"Necrosis coagulativa y gangrena seca.","e":"Desnaturação conserva o contorno da célula (coagulativa). A gangrena seca é coagulativa num membro."},{"p":"p1c","n":3,"t":"cita","tema":"acu","q":"Dos cambios patológicos que pueden sufrir las placas ateroscleróticas:","a":"Rotura, ulceración o erosión; hemorragia intraplaca; trombosis; formación de aneurisma; calcificación.","e":"Quaisquer dois da lista de complicações da placa."},{"p":"p1c","n":4,"t":"comp","tema":"nec","q":"La ________ es un cambio nuclear caracterizado por pérdida de basofilia de la cromatina debido a la disolución nuclear por degradación enzimática.","a":"Cariólisis.","e":"Cariólise: a DNase dissolve a cromatina e o núcleo some. O aluno transcreveu \"cariosis\"."},{"p":"p1c","n":6,"t":"comp","tema":"acu","q":"La tinción con carmín de Best o PAS da lugar a una coloración rosa violácea al depósito de ________.","a":"Glucógeno.","e":"PAS (ácido periódico de Schiff) e carmim de Best para glicogênio; confirma com digestão por diastase."},{"p":"p1c","n":8,"t":"cita","tema":"apo","q":"Cuadro comparativo: características entre apoptosis y necrosis (membrana plasmática, inflamación, tamaño celular, contexto).","a":"Necrosis: membrana rota, célula aumentada (tumefacción), con inflamación, siempre patológica. Apoptosis: membrana conservada, célula encogida, sin inflamación, forma cuerpos apoptóticos, fisiológica o patológica.","e":"Quadro clássico do Robbins: veja o comparativo da Clase 5."},{"p":"p1c","n":9,"t":"cita","tema":"apo","q":"La muerte causada por aumento de la permeabilidad de la membrana mitocondrial externa causa a veces la salida de unas proteínas al citosol.","a":"Presencia de citocromo c.","e":"Via mitocondrial: o citocromo c sai para o citosol e forma o apoptossomo.","nt":"Seção com quadro: Falla de bomba de sodio-potasio · Síntesis de proteínas aumentada · Piroptosis · Presencia de citocromo c · Colesterol LDL (lipoproteína de baja densidad) bajo · Gangrena seca · Necrosis caseosa · División celular aumentada."},{"p":"p1c","n":10,"t":"cita","tema":"nec","q":"Paciente de 70 años presenta un cuadro respiratorio de meses de evolución, y a nivel del vértice del pulmón derecho se observan imágenes granulomatosas.","a":"Necrosis caseosa.","e":"Ápice pulmonar, evolução de meses e granuloma: tuberculose."},{"p":"p1c","n":12,"t":"mc","tema":"nec","q":"Al microscopio óptico, en un patrón de lesión celular reversible, se podrá observar:","o":["Vacuolas lipídicas transparentes en el citoplasma de la célula","Presencia de masas de fosfolípidos y figuras de mielina","Calcificación […] que genera carbonatos de calcio","Aumento de eosinofilia por pérdida de ARN en el citoplasma"],"ok":[0],"w":["Ao microscópio óptico a lesão reversível mostra tumefação celular e alteração gordurosa (vacúolos lipídicos).","Grandes massas de fosfolipídios substituindo a célula são da necrose.","Calcificação é de tecido morto (distrófica). Alternativa truncada na transcrição.","Eosinofilia por perda de RNA é sinal de necrose."]},{"p":"p1c","n":14,"t":"mc","tema":"apo","q":"¿Qué trastorno clínico se asocia con apoptosis patológica?","o":["Infección en el pie derecho en un paciente diabético","Paciente con demencia por enfermedad de Parkinson","Verrugas cutáneas en un paciente con infección por papilomavirus","Disminución del flujo sanguíneo miocárdico por aterosclerosis coronaria"],"ok":[1],"w":["Pé diabético infectado é gangrena.","Proteínas mal dobradas causam estresse do retículo e apoptose dos neurônios: apoptose patológica.","O virus del papiloma humano bloqueia a apoptose.","Isquemia miocárdica dá necrose coagulativa."]},{"p":"p1c","n":15,"t":"mc","tema":"acu","q":"¿Cuál de los siguientes es un factor de riesgo adquirido para el desarrollo de ateromas?","o":["Sexo masculino","Consumo moderado de alcohol","Síndrome metabólico","Aumento del colesterol LDL"],"ok":[3],"w":["Sexo é fator não modificável.","Consumo moderado de álcool até sobe o HDL (lipoproteína de alta densidad); não é fator de risco.","Também é adquirido. Se o slide dela listar síndrome metabólica entre os fatores modificáveis, a questão tem duas certas.","LDL (lipoproteína de baja densidad) alto é o principal fator modificável, capaz sozinho de iniciar a aterosclerose."],"nt":"Questão ambígua: c e d são adquiridos. Na prova, a resposta esperada é a d."},{"p":"p1c","n":16,"t":"mc","tema":"pig","q":"Con respecto a la atrofia parda, ¿cuál de los siguientes es correcto?","o":["Ocurre en situaciones de pérdida de estimulación endocrina","Algunos de los residuos celulares del proceso constituyen los gránulos de hemosiderina","Las células atrofiadas intentan aumentar la demanda nutricional","Va acompañada de un incremento de vacuolas autofágicas"],"ok":[3],"w":["Perda de estímulo endócrino causa atrofia, mas a atrofia \"parda\" é a do idoso e da caquexia.","Os restos formam LIPOFUSCINA, não hemosiderina.","A atrofia REDUZ a demanda; é adaptação.","Na atrofia a autofagia aumenta; o que não se digere fica como corpos residuais de lipofuscina, que dão a cor parda."],"nt":"O tema é adaptação (P1), mas o pigmento lipofuscina é da P2."},{"p":"p1c","n":17,"t":"mc","tema":"apo","q":"En el estudio de la infección por VIH se observa a los linfocitos T citotóxicos provocando la muerte de las células infectadas por el virus. ¿Cuál de las siguientes sustancias inicia la muerte celular programada?","o":["BCL2","Endonucleasas","Caspasas","Gen TP53"],"ok":[2],"w":["BCL2 é antiapoptótica.","Endonucleases são executoras tardias que fragmentam o DNA, ativadas pelas caspases.","O linfócito T citotóxico usa perforina e granzima B (que ativa caspases diretamente) e FasL-Fas (caspase 8).","p53 inicia apoptose por dano no DNA, não pela via do linfócito citotóxico."]},{"p":"p1c","n":18,"t":"mc","tema":"nec","q":"Paciente de sexo femenino de 30 años de edad con diagnóstico de lupus eritematoso sistémico, enfermedad donde se producen reacciones inflamatorias de etiología inmunológica.","o":["Necrosis fibrinoide","Gangrena húmeda","Infarto blanco","Granuloma necrosado"],"ok":[0],"w":["Imunocomplexos e fibrina na parede dos vasos: aspecto rosa e amorfo. Típica de vasculites imunes (lupus eritematoso sistémico, PAN).","Gangrena úmida é isquemia com infecção.","Infarto branco é oclusão arterial em órgão de circulação terminal.","Granuloma necrosante é da tuberculose e dos fungos."]},{"p":"par1r","n":1,"t":"cita","tema":"acu","q":"Vesícula biliar con patrón en fresa, muestra microscópicamente numerosos [macrófagos] espumosos en la lámina propia.","a":"Aumento de colesterol (colesterolosis).","e":"Macrófagos cheios de colesterol na lâmina própria dão os pontinhos amarelos de \"morango\".","nt":"Seção com quadro: Sexo masculino · Necrosis fibrinoide · Necroptosis · Aumento de colesterol · Digestión enzimática · Colestasis · Displasia escamosa · Aumento de la mitosis celular · Metaplasia intestinal."},{"p":"par1r","n":3,"t":"cita","tema":"nec","q":"Mujer de 30 años fallece por lupus eritematoso sistémico, enfermedad donde hay reacciones inflamatorias de etiología inmunológica que han afectado las paredes de los vasos sanguíneos.","a":"Necrosis fibrinoide.","e":"Imunocomplexos e fibrina na parede vascular."},{"p":"par1r","n":4,"t":"cita","tema":"acu","q":"Dos factores de riesgo no modificables para el desarrollo de placas ateromatosas.","a":"Edad avanzada y sexo masculino (también antecedentes familiares o genética).","e":"Modificáveis: hiperlipidemia, hipertensão, tabagismo, diabetes."},{"p":"par1r","n":5,"t":"cita","tema":"acu","q":"Dos tinciones específicas para evidenciar las acumulaciones intracelulares de glucógeno.","a":"PAS (ácido periódico de Schiff) y carmín de Best.","e":"O PAS (ácido periódico de Schiff) tem de ser confirmado com diastase, porque também cora mucinas."},{"p":"par1r","n":6,"t":"cita","tema":"nec","q":"Dos cambios nucleares que se encuentran en una célula necrótica (no se aceptan descripciones).","a":"Picnosis y cariorrexis (o cariólisis).","e":"Ela pede o nome, não a descrição."},{"p":"par1r","n":7,"t":"comp","tema":"nec","q":"Los infartos que macroscópicamente presentan una forma de cuña, que se clasifican según su color, corresponden histológicamente a una necrosis ________.","a":"Coagulativa.","e":"Infarto em cunha (vértice no vaso ocluído) de órgão sólido: necrose coagulativa. Exceção: cérebro, liquefativa."},{"p":"par1r","n":8,"t":"comp","tema":"apo","q":"Las células tienen mecanismos por los cuales reparan el daño en el ADN, aunque cuando la afectación es demasiado grave la célula inicia un proceso de muerte que corresponde a ________.","a":"Apoptosis.","e":"Dano no DNA ativa p53, que induz PUMA e NOXA, que ativam BAX e BAK: via intrínseca."},{"p":"par1r","n":9,"t":"comp","tema":"pig","q":"Hombre de 70 años presenta atrofia parda en el corazón; en la autopsia el corazón pesa solo 250 g. Microscópicamente se ve que las fibras miocárdicas muestran cantidades excesivas de pigmento ________.","a":"Lipofuscina.","e":"Pigmento do desgaste, perinuclear, marrom-amarelado, de lipídios peroxidados."},{"p":"par1r","n":11,"t":"mc","tema":"nec","q":"Al microscopio electrónico, en un patrón de lesión celular reversible, se podrá observar:","o":["Rotura de la membrana plasmática","Dilatación masiva de la mitocondria","Presencia de figuras de mielina","Aumento de acidofilia"],"ok":[2],"w":["Ruptura de membrana é lesão irreversível.","Tumefação MASSIVA com grandes densidades amorfas é irreversível; na reversível a tumefação é leve.","Na microscopia eletrônica da lesão reversível: bolhas, perda de microvilos, tumefação mitocondrial leve, dilatação do retículo e figuras de mielina.","Acidofilia é achado de microscopia óptica e de necrose."]},{"p":"par1r","n":14,"t":"mc","tema":"nec","q":"¿Cuál de los siguientes trastornos clínicos se asocia a necrosis licuefactiva?","o":["Infección aguda por el virus de la hepatitis B","Lesión vascular en el pie derecho de un paciente diabético","Infarto del miocardio en paciente con aterosclerosis","Infarto cerebral por trombosis"],"ok":[3],"w":["Hepatite viral mata hepatócitos por apoptose (corpos de Councilman).","Isquemia do pé diabético dá gangrena (coagulativa; úmida se infectar).","Infarto do miocárdio é coagulativo.","Infarto cerebral é liquefativo."]},{"p":"par1r","n":15,"t":"mc","tema":"nec","q":"¿Cuál de los siguientes cambios morfológicos es más probable que apunte a una necrosis tubular aguda?","o":["Aumento de basofilia","Pérdida de microvellosidades","Tumefacción de las mitocondrias","Núcleos que sufren fragmentación"],"ok":[3],"w":["Na necrose aumenta a EOSINOFILIA, não a basofilia.","Perda de microvilos é lesão reversível.","Tumefação mitocondrial (leve) é lesão reversível.","Cariorrexe é sinal de célula morta."]},{"p":"par1r","n":17,"t":"mc","tema":"acu","q":"Una mujer de 69 años ha sufrido [episodios isquémicos] transitorios en los últimos 3 meses. En la [carótida] derecha se reseca una placa ateromatosa de aspecto firme, color amarillo oscuro a simple vista. Microscópicamente, ¿qué sustancias podemos encontrar en abundancia?","o":["Triglicéridos y lipoproteínas","Colesterol y ésteres de colesterol","Fosfolípidos y ácidos grasos libres","Triglicéridos y […]"],"ok":[1],"w":["Triglicérides não são o lipídio da placa.","O núcleo lipídico é colesterol e ésteres de colesterol, que cristalizam nas fendas de colesterol.","Fosfolipídios não predominam.","Triglicérides de novo; errada."]},{"p":"par1r","n":19,"t":"mc","tema":"acu","q":"Hombre de 73 años consulta por dolor abdominal; en el examen el hígado mide dos veces el tamaño normal, amarillo, de superficie lisa. Microscópicamente se muestran numerosas vacuolas transparentes en el citoplasma de los hepatocitos. ¿Cuál de las siguientes opciones podría ser la posible causa de las alteraciones del paciente?","o":["Infección por el virus de hepatitis","Alimentación rica en fibras","Consumo de alcohol","Anemia hemolítica"],"ok":[2],"w":["Hepatite viral dá apoptose e inflamação, não esteatose macro.","Fibra não causa esteatose.","Álcool é a causa mais comum de esteatose (com obesidade e diabetes).","Anemia hemolítica dá hemossiderose."]},{"p":"par1r","n":20,"t":"mc","tema":"nec","q":"Mujer de 78 años perdió el conocimiento de repente; no podía hablar ni mover el brazo derecho. A los dos meses una tomografía mostró una gran área quística en el lóbulo parietal izquierdo. ¿Cuál de los siguientes procesos patológicos es más probable que haya tenido lugar en el encéfalo?","o":["Necrosis gangrenosa con formación de cavitaciones","Infiltrados neutrofílicos con restos licuados","Lesión granulomatosa que presenta células multinucleadas","Granuloma que presenta centralmente depósitos de inmunocomplejos"],"ok":[1],"w":["Gangrena é termo de membro, não de cérebro.","Infarto cerebral é necrose liquefativa: neutrófilos e restos liquefeitos que, removidos, deixam a cavidade cística.","Granuloma é tuberculose, fungos e corpo estranho.","Não existe esse padrão."]},{"p":"final24","n":4,"t":"cita","tema":"inf","q":"Mediadores químicos denominados \"anafilotoxinas\":","a":"C3a y C5a.","e":"Fazem os mastócitos liberarem histamina (vasodilatação e permeabilidade). O C5a também é quimiotático. O C4a é anafilatoxina fraca."},{"p":"final24","n":5,"t":"comp","tema":"c7","q":"La calcificación ________ se caracteriza por depósitos de calcio en tejidos viables como consecuencia de hipercalcemia secundaria a un aumento de PTH.","a":"Metastásica.","e":"Tecido vivo e normal mais hipercalcemia (PTH alto, destruição óssea, vitamina D, insuficiência renal)."},{"p":"final24","n":10,"t":"cita","tema":"inf","q":"Las bacterias son fagocitadas por neutrófilos o bien sufren lisis. ¿Qué componente del plasma sanguíneo es más probable que facilite estos efectos?","a":"Complemento.","e":"C3b opsoniza e C5b-9 faz lise. Copiada do PEF (Q19)."},{"p":"final24","n":13,"t":"cita","tema":"c7","q":"Hombre de 67 años falleció debido a una insuficiencia cardíaca congestiva. En la autopsia el corazón pesa 580 g (normal 330 g) y muestra hipertrofia del ventrículo izquierdo y área valvular aórtica disminuida. El hallazgo bioquímico sérico solicitado antes fue normal. ¿Qué tipo de calcificación patológica explica mejor la afectación de la válvula aórtica?","a":"Calcificación distrófica.","e":"Estenose aórtica calcificada do idoso: desgaste valvar com cálcio sérico normal. A pista é \"bioquímica normal\"."},{"p":"final24","n":16,"t":"mc","tema":"c7","q":"Los cuerpos de psamoma corresponden a un tipo de calcificación:","o":["Displásica","Distrófica","Metastásica","Atrófica"],"ok":[1],"w":["\"Displásica\" não é tipo de calcificação.","Psamoma é calcificação distrófica em lâminas concêntricas sobre papilas de tumor.","Metastásica exige hipercalcemia.","\"Atrófica\" não é tipo de calcificação."]},{"p":"f24t","n":21,"t":"mc","tema":"inf","q":"Teniendo en cuenta los siguientes mediadores químicos y sus efectos correspondientes, marca la alternativa correcta:","o":["Leucotrieno B4, aumento de permeabilidad vascular","C5b-9, proceso de lisis celular","Prostaciclina, vasoconstrictor","IL-6, quimiotáctico"],"ok":[1],"w":["LTB4 é quimiotático. Quem aumenta permeabilidade são LTC4, D4 e E4.","O complexo de ataque à membrana abre poros e lisa a célula.","Prostaciclina é vasodilatadora. O vasoconstritor é o tromboxano A2.","IL-6 dá febre e fase aguda. Quimiotática é a IL-8."],"nt":"Na foto da folha é a questão 20; aqui vai com o número da transcrição (21) para não colidir com a nº 20 de leiomiossarcoma."},{"p":"final24","n":23,"t":"mc","tema":"inf","q":"Un grupo de pacientes recibe un inhibidor de la ciclooxigenasa 2 (COX-2). Los hombres adultos tenían artritis de pequeñas articulaciones. Refieren que el fármaco ha presentado ciertos efectos. ¿Cuál de los siguientes hallazgos es más probable que refiera el grupo que recibió el fármaco?","o":["Numerosos episodios febriles","Reducción del dolor articular","Mayor tumefacción de los tobillos"],"ok":[1],"w":["Inibir a COX-2 reduz a febre.","Menos PGE2, menos sensibilização dos nociceptores: menos dor.","Edema é efeito adverso possível, mas não o achado esperado."],"nt":"Mesma questão da P2 Turma C (Q17), copiada do PEF (Q15)."},{"p":"final24","n":29,"t":"cita","tema":"inf","q":"Fases del trayecto leucocitario que acontecen en la luz vascular:","a":"Marginación, rodamiento, adhesión.","e":"Transmigração e quimiotaxia já acontecem fora da luz.","nt":"Só na transcrição digitada, sem foto. Numeração do aluno."},{"p":"final24","n":30,"t":"cita","tema":"inf","q":"¿Cuáles son los mediadores químicos derivados de células que causan vasodilatación?","a":"Histamina y prostaglandinas (también óxido nítrico).","e":"A bradicinina dilata, mas é plasmática: o próprio aluno anotou \"bradicinina no es derivada de célula\".","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":32,"t":"cita","tema":"inf","q":"¿Cuál es el mediador en reacciones alérgicas?","a":"Histamina.","e":"Hipersensibilidade tipo I: IgE no mastócito, degranulação, histamina.","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":33,"t":"cita","tema":"inf","q":"Proceso de redistribución leucocitaria: los leucocitos adoptan una posición periférica a lo largo de la superficie endotelial.","a":"Marginación.","e":"É a frase que na recuperatória de 2023 aparece como falsa atribuída à \"migración\".","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":34,"t":"cita","tema":"inf","q":"Dos procesos de reclutamiento de leucocitos que acontecen en el tejido:","a":"Transmigración (diapédesis) y quimiotaxis.","e":"Complementa a pergunta da luz vascular (marginação, rolamento, adesão).","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":36,"t":"cita","tema":"nec","q":"La necrosis observada en el trastorno de una infección por bacteria piógena es un ejemplo de:","a":"Necrosis licuefactiva.","e":"Bactérias piogênicas atraem neutrófilos, cujas enzimas digerem o tecido: pus.","nt":"Só na transcrição digitada, sem foto."},{"p":"robbins","n":1,"t":"mc","tema":"inf","q":"Un hombre de 22 años presenta un dolor abdominal intenso en el cuadrante inferior derecho durante el último día. […] el apéndice está hinchado, eritematoso y parcialmente cubierto por un exudado amarillento. Se extirpa y un corte microscópico muestra infiltración con numerosos neutrófilos. El dolor experimentado por este paciente es [mediado principalmente por]:","o":["Complemento C3b e IgG","Interleucina-1 y factor de necrosis tumoral","Histamina y serotonina","Prostaglandina y bradicinina","Leucotrienos y HPETE"],"ok":[3],"w":["Opsoninas.","Febre e fase aguda.","Vasodilatação e permeabilidade imediatas, não a dor sustentada.","A PGE2 sensibiliza as terminações à bradicinina: dor. A aspirina alivia por isso.","Broncoespasmo, permeabilidade, quimiotaxia."],"nt":"Ela copiou na P2 Turma D (Q19)."},{"p":"robbins","n":4,"t":"mc","tema":"inf","q":"Una mujer de 58 años ha tenido tos con fiebre durante 3 días. Una radiografía de tórax revela infiltrados en el lóbulo inferior derecho. En un cultivo de esputo crece Streptococcus pneumoniae. La eliminación de estos organismos del parénquima pulmonar se lograría de manera más efectiva mediante la generación de ¿cuál de las siguientes sustancias por el principal tipo de célula inflamatoria que responde a esta infección?","o":["Factor activador de plaquetas","Prostaglandina E2","Calicreína","Leucotrieno B4","Peróxido de hidrógeno"],"ok":[4],"w":["PAF: agregação plaquetária, permeabilidade, broncoconstrição.","Vasodilatação, dor, febre.","Gera bradicinina.","Quimiotaxia.","H2O2 convertido pela mieloperoxidase em HOCl: o bactericida mais potente do neutrófilo."],"nt":"Ela copiou na P2 Turma C (Q18)."},{"p":"robbins","n":5,"t":"mc","tema":"inf","q":"Se realiza un estudio clínico de pacientes con infecciones faríngeas. El curso clínico más típico es de 3 días en promedio desde el momento de la aparición hasta que el paciente ve al médico. La mayoría de estos pacientes experimentan fiebre y escalofríos. En el examen físico, los hallazgos más comunes incluyen hinchazón, eritema y exudado purulento faríngeo. ¿Cuál de los siguientes tipos de inflamación tenían más probablemente estos pacientes?","o":["Granulomatoso","Agudo","Gangrenoso","Resolviendo","Crónico"],"ok":[1],"w":["Granulomatosa é crônica, com macrófagos epitelioides.","Curso curto (dias) e exsudato purulento, típico de estreptococo: inflamação aguda.","Gangrena é necrose de membro ou víscera.","Ainda há exsudato ativo; não está em resolução.","Crônica é de semanas a meses, com mononucleares."]},{"p":"robbins","n":7,"t":"mc","tema":"inf","q":"Una mujer de 22 años tiene un parto prematuro con rotura prematura de membranas fetales a las 20 semanas de gestación. Antes de ese momento, el embarazo se había desarrollado con normalidad. Dos días después, se produce un parto sin vida. El examen […] El parto prematuro probablemente estuvo mediado por los efectos de la liberación de ¿cuál de las siguientes sustancias?","o":["Inmunoglobulina","Prostaglandina","Complemento","Fibrinógeno","Linfocinas"],"ok":[1],"w":["Anticorpos não contraem o útero.","A corioamnionite libera prostaglandinas, que contraem o músculo liso uterino e desencadeiam o parto.","Complemento: opsonização, quimiotaxia, lise.","Fibrinogênio: coagulação e exsudato fibrinoso.","Linfocinas são da resposta imune adaptativa."],"nt":"O OCR perdeu uma linha do enunciado (marcada com […])."},{"p":"robbins","n":10,"t":"mc","tema":"inf","q":"Un hombre de 20 años ha tenido dolor al orinar durante 4 días. Se sospecha uretritis y se realiza un cultivo de Neisseria gonorrhoeae. En un frotis del exudado de la uretra del pene se encuentran numerosos neutrófilos. Estos neutrófilos experimentan diapédesis para llegar a los organismos. ¿Cuál de los siguientes mediadores químicos es más probable que provoque la exudación de neutrófilos?","o":["Histamina","Prostaglandina","Factor de Hageman","Bradicinina","Complemento"],"ok":[4],"w":["Histamina aumenta a permeabilidade, mas não atrai neutrófilos.","prostaglandinas: vasodilatação, dor, febre.","Hageman ativa coagulação e cininas.","Bradicinina: dor e permeabilidade.","O C5a é potente quimiotático para neutrófilos."]},{"p":"robbins","n":12,"t":"mc","tema":"nec","q":"Una mujer de 94 años ha presentado fiebre y tos durante los últimos 2 días. Se realiza un cultivo de Staphylococcus aureus en su esputo. Recibe un tratamiento antibiótico. Dos semanas después ya no tiene tos productiva, pero sigue teniendo fiebre. Una radiografía de tórax revela una densidad redondeada de 3 cm en el lóbulo inferior derecho cuyo contenido licuado forma un nivel hidroaéreo central. No hay infiltrados circundantes. ¿Cuál de las siguientes es la mejor descripción de este resultado de su neumonía?","o":["Cicatriz hipertrófica","Formación de abscesos","Regeneración","Carcinoma broncogénico","Inflamación crónica","Cavitación granulomatosa"],"ok":[1],"w":["Cicatriz não tem conteúdo líquido.","Cavidade com conteúdo liquefeito e nível hidroaéreo depois de S. aureus: necrose liquefativa, abscesso.","Regeneração devolve a arquitetura normal.","Nada sugere tumor.","Seria infiltrado mononuclear e fibrose, não cavidade líquida.","Cavidade granulomatosa é da tuberculosis (caseosa)."]},{"p":"robbins","n":13,"t":"mc","tema":"inf","q":"Una mujer de 36 años ha estado tomando ácido acetilsalicílico (aspirina) para la artritis durante los últimos 4 años. Su dolor articular se ha reducido temporalmente gracias a esta terapia. Sin embargo, ahora se ha identificado sangre oculta en sus heces. ¿Cuál de las siguientes sustancias es más probable que sea inhibida por la aspirina y cause esta complicación?","o":["Leucotrieno B4","Interleucina-1","Tromboxano","Bradicinina","Factor de Hageman"],"ok":[2],"w":["A aspirina não bloqueia a lipoxigenase.","IL-1 não depende da COX.","A aspirina acetila a COX das plaquetas de forma irreversível e corta o tromboxano A2: as plaquetas não tampam pequenas lesões e o paciente sangra.","Bradicinina vem das cininas.","Hageman é fator XII."]},{"p":"robbins","n":14,"t":"mc","tema":"inf","q":"Un hombre de 25 años se incrusta en el dedo una pequeña astilla de madera, que no retira y, en los tres días siguientes, la zona que la rodea se enrojece, se hincha y duele. Los neutrófilos migran al tejido lesionado. ¿Cuál de las siguientes sustancias se expresa en las células endoteliales y es la más importante para promover esta reacción inflamatoria?","o":["Interferón gamma","Factor de Hageman","Lisozima","E-selectina","Prostaciclina"],"ok":[3],"w":["IFN-γ ativa macrófagos.","Fator plasmático.","Enzima dos grânulos.","Selectinas endoteliais iniciam o rolamento. A P-selectina sai em minutos; a E-selectina é induzida por IL-1/TNF em horas.","Vasodilatador e antiagregante."]},{"p":"robbins","n":16,"t":"mc","tema":"inf","q":"Un hombre de 37 años ha tenido náuseas y vómitos durante 5 semanas. Ayer experimentó un episodio de hematemesis. En el examen físico no presenta hallazgos anormales. Se realiza una endoscopia del tracto gastrointestinal superior y se observa una lesión de 1,5 cm de diámetro en el antro gástrico con pérdida de la superficie epitelial. ¿Estos hallazgos son más típicos de cuál de los siguientes procesos patológicos?","o":["Absceso","Serositis","Granuloma","Gangrena","Úlcera"],"ok":[4],"w":["Pus dentro do tecido.","Inflamação de serosa.","Macrófagos epitelioides.","Necrose de membro.","Perda de superfície epitelial com inflamação."],"nt":"Ela copiou na P2 Turma C (Q20)."},{"p":"robbins","n":18,"t":"mc","tema":"inf","q":"Una mujer de 19 años que trabaja en un espacio cerrado pasa el día fuera trabajando en el jardín. No lleva sombrero ni protector solar. Esa noche, su pareja comenta que tiene la cara roja. ¿Cuál de los siguientes cambios dérmicos es más probable que explique su aspecto rojo?","o":["Agregación de neutrófilos","Hemorragia","Edema","Hemólisis","Vasodilatación"],"ok":[4],"w":["Neutrófilos não dão vermelhidão difusa.","Hemorragia não some quando a pele é comprimida.","Edema dá inchaço (tumor), não rubor.","Hemólise não tem relação.","Queimadura solar: prostaglandinas e histamina dilatam os vasos e dão rubor."]},{"p":"robbins","n":20,"t":"mc","tema":"nec","q":"Un hombre de 55 años tiene antecedentes de hipercolesterolemia con enfermedad de la arteria coronaria y sufrió un infarto de miocardio hace 2 años. Ahora presenta un dolor torácico subesternal opresivo. ¿Cuál de las siguientes pruebas de laboratorio es más útil para diagnosticar la causa de su dolor torácico?","o":["Aumento del recuento de glóbulos blancos","Tasa de sedimentación elevada","Disminución del complemento sérico","Aumento de la troponina sérica","Recuento de plaquetas disminuido","Aumento del colesterol sérico"],"ok":[3],"w":["Inespecífico.","Inespecífico.","Não tem relação.","A membrana da célula necrótica deixa sair troponina, específica do músculo cardíaco: prova de necrose miocárdica.","Não tem relação.","É fator de risco, não diagnóstico de infarto."]},{"p":"robbins","n":21,"t":"mc","tema":"inf","q":"Una niña de 15 años ha tenido episodios de estornudos con ojos llorosos y secreción nasal durante las últimas 2 semanas. En el examen físico presenta superficies de la mucosa nasal enrojecidas e hinchadas. Ha tenido episodios similares cada primavera y verano, cuando la cantidad de polen en el aire es alta. ¿Es más probable que sus síntomas estén mediados por la liberación de cuál de los siguientes mediadores químicos?","o":["Complemento C3b","Factor activador de plaquetas (PAF)","Factor de necrosis tumoral (TNF)","Histamina","Inmunoglobulina G"],"ok":[3],"w":["Opsonina.","Participa, mas não é o principal.","Citocina sistêmica.","Mastócitos perivasculares da mucosa nasal liberam histamina: vasodilatação e exsudação. Por isso se usa anti-histamínico.","A alergia é por IgE, e anticorpo não é mediador de vasodilatação."]},{"p":"robbins","n":22,"t":"mc","tema":"inf","q":"Un hombre de 45 años ha trabajado duro todo el día cargando montones de ladrillos para construir un muro. Toma un medicamento antiinflamatorio no esteroideo (ibuprofeno). ¿Cuál de los siguientes procesos es más probable que disminuya este medicamento en sus brazos?","o":["Trombosis","Dolor","Necrosis","Fibrinólisis","Formación de cicatrices"],"ok":[1],"w":["O efeito antiplaquetário do ibuprofeno é pequeno e reversível; não é o objetivo.","antiinflamatorios no esteroideos bloqueia a COX e reduz as prostaglandinas que causam dor.","Não há necrose.","antiinflamatorios no esteroideos não mexe na fibrinólise.","Não há cicatriz."]},{"p":"robbins","n":23,"t":"mc","tema":"inf","q":"A los pocos minutos de ser picado por una abeja, un hombre de 37 años presenta un marcado estridor respiratorio con disnea y […]. ¿[Cuál de los siguientes mediadores explica mejor los síntomas] de este hombre?","o":["Bradicinina","Complemento C5a","Óxido nítrico","Factor de necrosis tumoral","Histamina"],"ok":[4],"w":["Bradicinina é do angioedema hereditário, não da anafilaxia por picada.","C5a é anafilatoxina, mas o mediador direto é a histamina.","NO dilata vasos, mas não é o mediador inicial.","Citocina, mais lenta.","Anafilaxia (tipo I): o antígeno se liga à IgE no mastócito, que libera histamina em minutos."],"nt":"O OCR perdeu uma linha do enunciado."},{"p":"robbins","n":25,"t":"mc","tema":"inf","q":"En un experimento, se añaden organismos del tipo Enterobacter cloacae a una solución que contiene leucocitos y plasma sanguíneo. […] destruyen más bacterias. ¿Cuál de las siguientes sustancias presentes en el plasma es más probable que produzca este efecto?","o":["Complemento C3b","Glutatión peroxidasa","Inmunoglobulina M","P-selectina","NADPH oxidasa"],"ok":[0],"w":["O C3b é opsonina: recobre a bactéria e o fagócito a engole mais fácil.","Antioxidante intracelular.","IgM ativa o complemento, mas os fagócitos não têm receptor para ela.","Molécula do endotélio, não do plasma.","Enzima dentro do fagócito, não do plasma."],"nt":"O OCR perdeu uma linha do enunciado."},{"p":"robbins","n":27,"t":"mc","tema":"inf","q":"Un hombre de 31 años tiene una herida punzante en el pulgar, que se infecta secundariamente con organismos del tipo […]. ¿[Cuál es la función de los vasos linfáticos] para producir una respuesta inmunitaria específica a estos organismos?","o":["Transportar linfocitos a sitios de tejido periférico","Eliminar el líquido del tejido extravascular","Transportar células presentadoras de antígenos","Servir como vía de diseminación de la infección","Proporcionar un punto de emigración para los neutrófilos"],"ok":[2],"w":["Linfócitos chegam ao tecido pelo sangue.","Drenam o edema, mas isso não gera resposta específica.","Células dendríticas e macrófagos levam o antígeno aos linfonodos, onde encontram os linfócitos específicos.","Pode acontecer (linfangite), mas não produz resposta específica.","Neutrófilos saem pelas vênulas pós-capilares."],"nt":"O OCR perdeu uma linha do enunciado."},{"p":"robbins","n":29,"t":"mc","tema":"inf","q":"Un hombre de 55 años con antecedentes de enfermedad pulmonar obstructiva crónica presenta insuficiencia cardíaca congestiva que empeora. Ha notado un aumento de la disnea y la ortopnea durante los últimos 2 meses. En el examen físico hay matidez a la percusión en las bases pulmonares. Una radiografía de tórax muestra derrames pleurales bilaterales. Se realiza una toracocentesis izquierda y se obtienen 500 ml de líquido. ¿Cuál de las siguientes características de este líquido indicaría con mayor probabilidad que se trata de un trasudado?","o":["Aspecto nublado","Alto contenido de proteínas","Recuento bajo de leucocitos","Presencia de fibrina","Gran tamaño del derrame"],"ok":[2],"w":["Turvo é exsudato.","Proteína alta é exsudato.","Transudato é ultrafiltrado de plasma: poucas células, pouca proteína, transparente.","Fibrina é exsudato.","Volume não distingue."],"nt":"É a mesma situação das P2, só que perguntando o contrário (transudato)."},{"p":"robbins","n":32,"t":"mc","tema":"inf","q":"Una niña de 9 años sufre una pequeña laceración de 0,5 cm de longitud en el dedo índice derecho mientras juega a la \"Reina de espadas\" con un abrecartas. ¿Cuál de las siguientes sustancias, al entrar en contacto con la membrana basal vascular lesionada, […]?","o":["Tromboxano","Plasmina","Factor activador de plaquetas","Factor de Hageman","Histamina"],"ok":[3],"w":["Vem das plaquetas ativadas, não do contato com a membrana basal.","Produto final da fibrinólise.","Liberado por células.","O fator XII (Hageman) se ativa ao tocar colágeno e membrana basal expostos e dispara coagulação, cininas, fibrinólise e complemento.","Vem do mastócito."],"nt":"O OCR perdeu o final do enunciado (\"se activa…\")."},{"p":"robbins","n":33,"t":"mc","tema":"inf","q":"Una mujer de 65 años ha tenido fiebre durante el último día. En el examen físico su temperatura es de 39 °C y la presión arterial de 90/50 mmHg con frecuencia cardíaca de 106/min. Los estudios de laboratorio muestran un recuento de leucocitos de 12.510/µl y un recuento diferencial de 78 segmentados, 8 bandas, 11 linfocitos y 3 monocitos. Un hemocultivo es positivo para Escherichia coli. Su presión venosa central disminuye notablemente. Entra en shock como resultado de la liberación inapropiada generalizada de un mediador químico derivado de los macrófagos. Desarrolla insuficiencia orgánica múltiple. ¿Cuál de los siguientes mediadores es más probable que produzca estos hallazgos?","o":["Óxido nítrico","Bradicinina","Histamina","Prostaciclina","Complemento C3a"],"ok":[0],"w":["Macrófagos ativados por endotoxina produzem NO em grande quantidade (iNOS): vasodilatação sistêmica, hipotensão e choque séptico.","Plasmática, não macrofágica.","Vem de mastócitos.","Vem do endotélio.","Plasmático."]},{"p":"robbins","n":35,"t":"mc","tema":"inf","q":"Una primigrávida de 24 años se encuentra en las últimas etapas del segundo trimestre de embarazo. Siente de repente un dolor abdominal bajo en forma de cólico. A esto le sigue inmediatamente la expulsión de líquido por la vagina junto con una secreción maloliente. El feto nace muerto dos días después. El examen de la placenta muestra infiltrados neutrofílicos extensos en el corion y el amnios. ¿Cuál de los siguientes organismos es más probable que sea responsable de estos hallazgos?","o":["Mycobacterium tuberculosis","Virus del herpes simple","Escherichia coli","Treponema pallidum","Toxoplasma gondii"],"ok":[2],"w":["tuberculosis dá granuloma.","Vírus dão infiltrado linfocitário.","Corioamnionite aguda com neutrófilos: bactérias ascendentes (E. coli, estreptococo do grupo B).","Sífilis dá plasmócitos e vasculite.","Toxoplasma é parasita intracelular, sem pus."]},{"p":"robbins","n":37,"t":"mc","tema":"inf","q":"Un hombre de 45 años ha tenido fiebre y tos seca durante 3 días, y ahora tiene dificultad para respirar y tos productiva de esputo. En la exploración física su temperatura es de 38,5 °C. Se auscultan estertores difusos en los campos pulmonares inferiores. Una radiografía de tórax muestra un derrame pleural derecho. Se realiza una toracocentesis derecha. El líquido obtenido tiene un aspecto turbio con un recuento celular que muestra 15.500 leucocitos por microlitro, el 98 % de los cuales son neutrófilos. ¿Cuál de los siguientes términos describe mejor su proceso pleural?","o":["Inflamación serosa","Inflamación purulenta","Inflamación fibrinosa","Inflamación crónica","Inflamación granulomatosa"],"ok":[1],"w":["Serosa é clara e pobre em células.","Turvo com 98 % de neutrófilos: exsudato purulento. Na pleura, empiema.","Fibrinosa não é turva por neutrófilos.","Crônica tem mononucleares.","Granulomatosa tem macrófagos epitelioides."]},{"p":"robbins","n":38,"t":"mc","tema":"inf","q":"Una mujer de 52 años sin problemas médicos importantes emprende un largo vuelo en avión a través del océano Pacífico. Al llegar al aeropuerto Kingsford Smith de Sídney después del vuelo desde Los Ángeles, no puede volver a ponerse los zapatos. No siente dolor ni sensibilidad. ¿Cuál de las siguientes es la explicación más probable para este fenómeno?","o":["La activación del factor de Hageman ha llevado a la producción de bradicinina","En la sección de primera clase se sirvieron muchas bebidas","Se desarrolló trombosis de la vena femoral","Le apareció celulitis en las piernas","La presión hidrostática venosa aumentó"],"ok":[4],"w":["Não há lesão vascular nem inflamação.","Brincadeira do banco; não explica edema bilateral.","Trombose dá edema unilateral e dor.","Celulite dói e fica vermelha.","Horas sentado reduzem o retorno venoso e linfático; a pressão hidrostática sobe e forma edema (transudato), sem dor."],"nt":"Edema hemodinâmico (transudato): serve para contrastar com o exsudato da inflamação."},{"p":"robbins","n":40,"t":"mc","tema":"inf","q":"Un hombre de 56 años ha tenido dificultad respiratoria cada vez mayor durante la última semana. En el examen físico no presenta fiebre. La auscultación del tórax revela disminución de los ruidos respiratorios y matidez a la percusión bilateral. Hay edemas con fóvea 2+ a la altura de los muslos. Una radiografía de tórax revela derrames pleurales bilaterales. ¿Cuál de los siguientes hallazgos de las pruebas de laboratorio es más probable que presente?","o":["Hipoalbuminemia","Glucosuria","Neutrofilia","Anemia","Hipernatremia"],"ok":[0],"w":["Albumina baixa reduz a pressão oncótica: transudato em cavidades e edema com cacifo.","Não causa edema.","Sem febre nem infecção.","Não causa derrame.","Não é a causa típica."],"nt":"Edema hemodinâmico (transudato), para contrastar com o exsudato."},{"p":"pef","n":1,"t":"mc","tema":"inf","q":"Un niño de 11 años se hace un corte en la mano al caerse. La herida se infecta. Las bacterias se expanden a la matriz extracelular alrededor de los capilares. En la respuesta inflamatoria frente a esta infección, ¿cuál de las siguientes células elimina las bacterias?","o":["Linfocito B","Fibroblasto","Macrófago","Mastocito","Linfocito T"],"ok":[2],"w":["Vira plasmócito e faz anticorpo; não fagocita.","Faz colágeno no reparo.","Fagócito \"faxineiro\" do tecido, derivado do monócito.","Libera mediadores; não fagocita.","Imunidade celular; não fagocita bactéria."]},{"p":"pef","n":2,"t":"mc","tema":"inf","q":"Una mujer de 53 años presenta fiebre alta y tos productiva con esputos amarillentos de 2 días de evolución. Sus constantes vitales son 37,8 °C de temperatura, frecuencia cardíaca de 103 latidos/min, frecuencia respiratoria de 25 respiraciones/min y presión arterial de 100/60 mmHg. En la auscultación del tórax se aprecian crepitantes en ambas bases pulmonares. La radiografía de tórax muestra infiltrados pulmonares parcheados bilaterales. La figura se corresponde con la imagen microscópica del pulmón. ¿Cuál de los siguientes tipos de células inflamatorias es más probable que se observe en abundancia en la muestra de esputo?","o":["Células gigantes de Langhans","Macrófagos","Mastocitos","Neutrófilos","Linfocitos T"],"ok":[3],"w":["Granulomatosa.","Aumentam depois, para limpar.","Alergia e anafilaxia.","Broncopneumonia bacteriana aguda: neutrófilos enchem os alvéolos e dão o escarro purulento.","Inflamação crônica."]},{"p":"pef","n":3,"t":"mc","tema":"inf","q":"Una niña de 4 años lleva 2 días con diarrea de volumen alto. En el momento de la exploración está deshidratada. La muestra de heces evaluada mediante análisis serológico es positiva para rotavirus. Recibe tratamiento con líquidos intravenosos y se recupera. ¿Cuál de los siguientes componentes está presente en las células intestinales para reconocer el ARN de doble cadena de este virus y activar los factores de transcripción que regulan al alza la producción de interferón con vistas a eliminarlo?","o":["Caspasa 1","Receptor del complemento","Lectina","Receptor de linfocitos T","Receptor de tipo señuelo (toll)"],"ok":[4],"w":["Caspase 1 é do inflamassoma (IL-1β), não reconhece RNA.","Reconhece C3b.","Lectinas reconhecem açúcares da parede microbiana.","TCR reconhece peptídeo no MHC.","TLR3 reconhece RNA de fita dupla e ativa NF-κB/IRF: interferon."]},{"p":"pef","n":4,"t":"mc","tema":"inf","q":"Un hombre de 72 años con enfisema grave ha presentado insuficiencia ventricular derecha progresiva en los últimos 5 años. Lleva 4 días con fiebre y disnea en aumento. Una radiografía de tórax muestra acumulación de líquido en los espacios pleurales. El líquido obtenido mediante toracocentesis tiene una densidad de 1,030 y contiene neutrófilos en degeneración. ¿Cuál de las siguientes es la causa más probable de esta acumulación de líquido si sufre variaciones?","o":["Presión oncótica","Diapédesis leucocítica","Presión linfática","Retención renal de sodio","Permeabilidad vascular"],"ok":[4],"w":["Pressão oncótica baixa dá transudato.","Diapedese traz células, não o líquido.","Obstrução linfática dá linfedema.","Retenção de sódio dá transudato.","Densidade 1,030 e neutrófilos: exsudato, por aumento de permeabilidade."]},{"p":"pef","n":5,"t":"mc","tema":"inf","q":"Un hombre de 35 años presenta disnea progresiva en las últimas 24 h. La radiografía de tórax muestra un derrame pleural bilateral de gran tamaño. Mediante toracocentesis se obtienen 500 ml de un líquido amarillo ligeramente turbio de la cavidad pleural derecha. El examen citológico del líquido revela múltiples neutrófilos, pero no hay linfocitos ni eritrocitos. ¿Cuál de los siguientes mecanismos contribuye más a la acumulación del líquido pleural?","o":["Vasoconstricción arteriolar","Contracción endotelial","Inhibición de la adhesión plaquetaria","Obstrucción linfática","Liberación de lisosomas por los neutrófilos"],"ok":[1],"w":["Transitória; não gera exsudato.","Mecanismo mais comum e precoce do aumento de permeabilidade.","Não tem relação.","Linfedema.","Lesa tecido, mas não é o mecanismo principal."],"nt":"Ela copiou na P2 Turma D (Q18)."},{"p":"pef","n":6,"t":"mc","tema":"inf","q":"Un niño de 6 años tiene antecedentes de infecciones de repetición por bacterias piógenas, incluidas Staphylococcus aureus y Streptococcus pneumoniae. Las infecciones se acompañan de leucocitosis con neutrofilia. El examen microscópico de una biopsia obtenida de un área de necrosis de tejido blando muestra microorganismos, pero muy pocos neutrófilos. Un análisis de la función de los neutrófilos muestra un defecto en el rodamiento. ¿Cuál de las siguientes moléculas es la causa más probable de la mayor susceptibilidad de este niño a las infecciones si sufre defectos?","o":["C3b del complemento","Integrinas","Leucotrieno B4","NADPH oxidasa","Selectinas"],"ok":[4],"w":["Opsonização.","Adesão firme.","Quimiotaxia.","Morte microbiana.","Rolamento depende de selectinas (deficiência de adesão leucocitária tipo 2)."]},{"p":"pef","n":7,"t":"mc","tema":"inf","q":"En un experimento se introducen bacterias en un preparado de tejido perfundido. Los leucocitos salen de los vasos y migran a la zona de inoculación bacteriana. ¿Cuál de las siguientes sustancias es más probable que medie el desplazamiento de esos leucocitos?","o":["Bradicinina","Quimiocinas","C3a del complemento","Histamina","Prostaglandinas"],"ok":[1],"w":["Dor e permeabilidade.","Quimiocinas (IL-8) guiam a migração.","Anafilatoxina fraca; o quimiotático é o C5a.","Permeabilidade.","Vasodilatação, dor, febre."]},{"p":"pef","n":8,"t":"mc","tema":"inf","q":"Un niño de 12 meses con infecciones de repetición en los últimos 6 meses tiene fiebre y tos de 3 días de evolución. Una tinción de Gram del esputo muestra muchos cocos grampositivos en cadenas. El hemograma revela neutrofilia. Las pruebas de laboratorio […] matan a los microorganismos rápidamente en presencia de suero […] migran normalmente en un análisis de quimiotaxinas. ¿Cuál de las siguientes causas es más probable que explique la mayor susceptibilidad del niño a las infecciones?","o":["Anomalía de la expresión de selectina","Reducción de la opsonización","Producción insuficiente de peróxido de hidrógeno por los neutrófilos","Déficit de integrinas","Defecto de las proteínas de los microtúbulos en las células fagocíticas"],"ok":[1],"w":["Migração está normal.","Os neutrófilos matam bem com soro normal: o defeito está no soro do paciente, falta opsonina.","Matam rápido, então o H2O2 está bem.","Migração normal.","Chédiak-Higashi; a migração estaria alterada."],"nt":"O OCR perdeu trechos do enunciado."},{"p":"pef","n":9,"t":"mc","tema":"inf","q":"Un niño de 5 años tiene antecedentes de infecciones bacterianas recidivantes, incluidas neumonía y otitis media. El análisis de los leucocitos recogidos de sangre periférica muestra un déficit de mieloperoxidasa. ¿Cuál de los procesos siguientes es la causa más […] cuando se reduce?","o":["Elaboración de peróxido de hidrógeno (H2O2)","Formación de radical hidroxihaluro (HOCl)","Fracaso de la migración debido a déficit del complemento","Consumo de oxígeno por las células fagocíticas","Producción de prostaglandinas"],"ok":[1],"w":["O H2O2 é feito pela NADPH oxidase, que está normal.","A mieloperoxidase transforma H2O2 + Cl⁻ em HOCl; sem ela, o hipoclorito falta.","Não há defeito de complemento.","O consumo de O2 (explosão respiratória) é da NADPH oxidase.","Não depende da MPO."],"nt":"O OCR perdeu um trecho do enunciado."},{"p":"pef","n":10,"t":"mc","tema":"inf","q":"En un experimento, se analizan los neutrófilos recogidos de sangre periférica en busca de un \"estallido\" de consumo de oxígeno. ¿En cuál de los siguientes procesos este estallido respiratorio es un paso esencial en la respuesta inflamatoria aguda?","o":["Unión a las células endoteliales","Generación de actividad microbicida","Aumento de la producción en la médula ósea","Opsonización de bacterias","Fagocitosis de bacterias"],"ok":[1],"w":["Adesão não gasta O2 em explosão.","A explosão respiratória gera EROs que matam o micróbio no fagolisossomo.","Produção medular depende de fatores estimulantes de colônias.","Opsonização é do plasma.","A fagocitose vem antes da explosão."]},{"p":"pef","n":14,"t":"mc","tema":"inf","q":"Una mujer alérgica a los gatos visita a un vecino que tiene varios de estos animales. Durante la visita, inhala epitelio de gato y a los pocos minutos desarrolla congestión nasal con secreción nasal abundante. ¿Cuál de las siguientes sustancias es más probable que provoque estos síntomas?","o":["Bradicinina","C5a del complemento","Histamina","Interleucina 1 (IL-1)","Fosfolipasa C","Factor de necrosis tumoral (TNF)"],"ok":[2],"w":["Não é da alergia.","Anafilatoxina, mas o efetor é a histamina.","Minutos depois do alérgeno: IgE no mastócito, histamina.","Febre.","Enzima de sinalização.","Citocina sistêmica."]},{"p":"pef","n":16,"t":"mc","tema":"inf","q":"Una mujer de 19 años desarrolla irritación de garganta y fiebre el día anterior. En la exploración física se observan eritema y edema faríngeo. Los hallazgos de laboratorio revelan leucocitosis. Se le administra naproxeno. ¿A cuál de los siguientes elementos de la respuesta inflamatoria aguda afecta más este fármaco?","o":["Quimiotaxia","Migración","Leucocitosis","Fagocitosis","Vasodilatación"],"ok":[4],"w":["Não depende da COX.","Não depende da COX.","Medula, citocinas.","Não depende da COX.","antiinflamatorios no esteroideos reduz as prostaglandinas vasodilatadoras."]},{"p":"pef","n":17,"t":"mc","tema":"inf","q":"Una mujer de 35 años toma ácido acetilsalicílico para la artritis. Aunque el dolor articular disminuye con este tratamiento, el proceso inflamatorio continúa. ¿Cuál de los siguientes mediadores es el principal responsable del alivio del dolor cuando se reduce su síntesis por acción del ácido acetilsalicílico?","o":["C1q del complemento","Histamina","Leucotrieno E4","Óxido nítrico","Prostaglandinas"],"ok":[4],"w":["Complemento.","Mastócito; aspirina não mexe.","Lipoxigenase; aspirina não bloqueia.","NO sintase.","A aspirina bloqueia a COX; menos prostaglandinas, menos dor."]},{"p":"pef","n":18,"t":"mc","tema":"inf","q":"Una mujer de 77 años pierde el conocimiento súbitamente, con ausencia de movimiento en la parte derecha de su organismo. La angiografía cerebral muestra una oclusión de la arteria cerebral media. ¿Cuál de los siguientes mediadores es más útil para prevenir que se agrave la lesión isquémica en la corteza cerebral?","o":["Bradicinina","Leucotrieno E4","Óxido nítrico","Factor activador de plaquetas","Tromboxano A2"],"ok":[2],"w":["Aumenta permeabilidade e edema.","Vasoconstrição.","Vasodilata e inibe a agregação plaquetária e a adesão de leucócitos.","Agrega plaquetas.","Vasoconstrição e agregação."]},{"p":"pef","n":19,"t":"mc","tema":"inf","q":"En un experimento, se inoculan bacterias en alícuotas de sangre humana normal que ha sido tratada con un anticoagulante. Se observa que las bacterias son fagocitadas por neutrófilos o bien sufren lisis. ¿Cuál de los siguientes componentes del plasma sanguíneo es más probable que facilite estos efectos?","o":["Complemento","Fibrina","Calicreína","Plasmina","Trombina"],"ok":[0],"w":["C3b opsoniza e C5b-9 lisa.","Coágulo.","Gera bradicinina.","Fibrinólise.","Coagulação."],"nt":"Ela copiou no Examen Final (Q10) e na P2 Turma D (Q9)."},{"p":"pef","n":20,"t":"mc","tema":"inf","q":"Los pacientes con daño endotelial extenso en relación con una sepsis por Escherichia coli presentan consumo de factores de la coagulación, así como una respuesta inflamatoria generalizada. ¿Cuál de las siguientes sustancias, cuya cantidad disminuye con la administración de proteína C activada, es más probable que reduzca esta respuesta inflamatoria?","o":["Complemento","Fibrina","Calicreína","Plasmina","Trombina"],"ok":[4],"w":["Não é alvo da proteína C.","Produto, não mediador inflamatório.","Via das cininas.","Fibrinólise.","A proteína C ativada inativa os fatores Va e VIIIa e reduz a trombina, que ativa receptores PAR e inflama o endotélio."]},{"p":"pef","n":21,"t":"mc","tema":"inf","q":"Una mujer de 95 años toca una olla llena de agua hirviendo. A las 2 h tiene eritema marcado en la piel de los dedos de la mano y pequeñas ampollas en las yemas de los dedos. ¿Cuál de las siguientes respuestas inflamatorias ha provocado este accidente?","o":["Inflamación fibrinosa","Inflamación granulomatosa","Inflamación purulenta","Inflamación serosa","Úlceras"],"ok":[3],"w":["Fibrina em serosas.","Crônica.","Infecção piogênica.","Bolha de queimadura: líquido seroso pobre em células.","Não há perda de epitélio."],"nt":"Ela usou a mesma ideia na recuperatória de 2023 (Q1) e na P2 da p. 97 (Q5)."},{"p":"pef","n":22,"t":"mc","tema":"nec","q":"Una mujer de 24 años sexualmente activa ha notado dolor abdominal bajo en el último día. Su temperatura es 37,9 °C y, a la palpación, la parte inferior izquierda del abdomen es muy dolorosa. Los resultados de laboratorio son leucocitos totales de 29.000/mm³ con el 75 % de neutrófilos segmentados, el 6 % de cayados, el 14 % de linfocitos y el 5 % de monocitos. La laparotomía pone de manifiesto una trompa de Falopio enrojecida, distendida y llena de líquido que está a punto de romperse. Se realiza una salpingectomía izquierda. ¿Cuál de los siguientes hallazgos es más probable observar en el examen microscópico de la trompa de Falopio resecada?","o":["Proliferación fibroblástica","Células gigantes de Langhans","Necrosis por licuefacción","Infiltrados mononucleares","Metaplasia escamosa"],"ok":[2],"w":["Reparo, mais tardio.","tuberculosis.","Infecção bacteriana aguda (piossalpinge): neutrófilos e necrose liquefativa (pus).","Crônica.","Adaptação."]},{"p":"pef","n":23,"t":"mc","tema":"inf","q":"Un hombre de 68 años presenta disnea progresiva desde hace 1 semana. En la exploración física la temperatura es de 38,3 °C. La percusión revela un tono mate en los campos pulmonares izquierdos. En la toracocentesis realizada en la cavidad pleural izquierda se obtienen 800 ml de líquido amarillento y turbio que tiene un recuento de leucocitos de 2.500/mm³ con el 98 % de neutrófilos y el 2 % de linfocitos. Una tinción de Gram del líquido muestra cocos grampositivos en racimos. ¿Cuál de los siguientes términos describe mejor el proceso que está teniendo lugar en la cavidad pleural izquierda?","o":["Absceso","Inflamación crónica","Edema","Inflamación fibrinosa","Exudado purulento","Derrame seroso"],"ok":[4],"w":["Abscesso é localizado dentro de tecido.","Teria mononucleares.","Edema é transudato.","Fibrina sem pus.","Turvo, neutrófilos e cocos: pus (empiema).","Seroso é claro."],"nt":"Ela copiou na P2 Turma D (Q17)."},{"p":"pef","n":24,"t":"mc","tema":"inf","q":"Una mujer de 87 años lleva 2 días con tos productiva y esputos amarillentos. En la exploración su temperatura es de 37 °C. La radiografía de tórax muestra infiltrados dispersos bilaterales. La sangre periférica revela leucocitosis. Una semana después no tiene fiebre. ¿Cuál de los siguientes resultados es el más probable de su enfermedad pulmonar?","o":["Inflamación crónica","Cicatrices fibrosas","Neoplasia","Resolución","Úlceras"],"ok":[3],"w":["Não há persistência.","Cicatriz se houvesse destruição da trama.","Não tem relação.","Pneumonia bacteriana tratada, com estroma preservado: resolução completa.","Não há perda de epitélio."]},{"p":"pef","n":26,"t":"mc","tema":"nec","q":"Una mujer de 92 años es diagnosticada de neumonía por Staphylococcus aureus y recibe un ciclo de tratamiento antibiótico. A las 2 semanas ya no tiene tos productiva, pero aún presenta una temperatura de 38,1 °C. La TC de tórax muestra los hallazgos de la figura. ¿Cuál de los siguientes términos describe mejor la evolución de la neumonía de la paciente?","o":["Formación de abscesos","Resolución completa","Cicatrices fibrosas","Inflamación crónica","Regeneración tisular"],"ok":[0],"w":["S. aureus e febre persistente: abscesso (necrose liquefativa).","Ainda tem febre.","Seria sem febre.","Não é a melhor descrição.","Não houve."]},{"p":"pef","n":34,"t":"mc","tema":"inf","q":"Una niña de 8 años presenta dificultades para la deglución desde el día anterior. En la exploración tiene la faringe edematosa y eritematosa con un exudado amarillo sobresaliente. Las pruebas de laboratorio muestran neutrofilia. El cultivo de la faringe identifica Streptococcus pyogenes (estreptococo del grupo A). ¿Cuál de las siguientes sustancias es más probable que aumente en respuesta a los pirógenos liberados por este microorganismo?","o":["Factor de Hageman","Inmunoglobulina E","Interleucina 12 (IL-12)","Óxido nítrico","Prostaglandinas"],"ok":[4],"w":["Coagulação e cininas.","Alergia.","Ativa Th1 e NK.","Vasodilatação.","Pirógenos (IL-1, TNF) induzem COX-2 e PGE2 no hipotálamo: febre."]},{"p":"pef","n":35,"t":"mc","tema":"inf","q":"Un hombre de 41 años sufre cefalea intensa desde hace 2 días. En la exploración la temperatura es de 39,2 °C. Se realiza una punción lumbar, y el líquido cefalorraquídeo obtenido tiene 910 leucocitos/mm³ con el 94 % de neutrófilos y el 6 % de linfocitos. ¿Cuál de las siguientes sustancias es el mediador más probable de la fiebre de este hombre?","o":["Bradicinina","Histamina","Leucotrieno B4","Óxido nítrico","Factor de necrosis tumoral (TNF)"],"ok":[4],"w":["Dor.","Vasodilatação.","Quimiotaxia.","Vasodilatação.","TNF e IL-1 são os pirógenos endógenos."]},{"p":"pef","n":36,"t":"mc","tema":"inf","q":"Un hombre de 43 años con una comunicación interventricular lleva 2 días con tos y fiebre. En la exploración su temperatura es 37,6 °C y tiene un soplo cardíaco. En un hemocultivo crece Streptococcus del grupo viridans. La velocidad de sedimentación globular (VSG) está aumentada. Las células microbianas son opsonizadas y eliminadas. ¿Cuál de los siguientes mediadores químicos es más importante en la producción de estos hallazgos?","o":["Bradicinina","Proteína C reactiva","Interferón γ","Óxido nítrico","Prostaglandina","Factor de necrosis tumoral (TNF)"],"ok":[1],"w":["Dor.","Proteína de fase aguda (feita no fígado por IL-6) que opsoniza bactérias e eleva a VSG.","Ativa macrófagos.","Vasodilatação.","Febre.","Estimula a fase aguda, mas quem opsoniza é a PCR."]},{"p":"final24","n":1,"t":"cita","tema":"neo","q":"Características morfológicas (microscópicas) de malignidad:","a":"Núcleo hipercromático y figuras mitóticas atípicas.","e":"Marcadores de anaplasia: pleomorfismo, núcleos grandes e hipercromáticos com relação núcleo:citoplasma perto de 1:1 (normal 1:4 a 1:6), nucléolos grandes e mitoses atípicas e grotescas (slides 30 a 33 da Clase 11)."},{"p":"final24","n":7,"t":"comp","tema":"neo","q":"La ________ es la magnitud en que las células neoplásicas se asemejan en su función y forma a las células correspondientes del parénquima sano.","a":"Diferenciación.","e":"Tumor bem diferenciado lembra o tecido de origem; benigno costuma ser bem diferenciado."},{"p":"final24","n":8,"t":"comp","tema":"neo","q":"La falta de diferenciación se conoce como ________.","a":"Anaplasia.","e":"Anaplasia = falta de diferenciação, marca de malignidade."},{"p":"final24","n":11,"t":"cita","tema":"neo","q":"SECCIÓN III · Parea las nomenclaturas con su definición (solo 2 son correctas; las demás quedan en blanco). Nomenclaturas: A) Quiste dermoide · B) Hamartoma. Definiciones: (1) Masas desorganizadas benignas de células propias del lugar afectado · (2) Teratoma quístico que se diferencia sobre todo de las líneas ectodérmicas · (3) Presencia de tejido de aspecto normal en localización anormal · (4) Forma especializada de teratoma que contiene cartílago, tejido adiposo, glándulas intestinales y numerosos folículos tiroideos · (5) Proyección macroscópica visible sobre la superficie mucosa.","a":"B Hamartoma = (1) masas desorganizadas benignas de células propias del lugar afectado. A Quiste dermoide = (2) teratoma quístico que se diferencia sobre todo de las líneas ectodérmicas.","e":"O enunciado diz que só 2 estão certas, as outras ficam em branco. O quiste dermoide é o teratoma quístico do ovário, tumor cheio de pelos, glândulas sebáceas e dentes; a definição com cartilagem, tecido adiposo e folículos tiroideos é do struma ovarii, outra forma de teratoma (slide 22 da Clase 11)."},{"p":"final24","n":14,"t":"cita","tema":"neo","q":"Mujer de 59 años con dolor retroesternal con ardor leve después de las comidas durante los últimos 4 años. La biopsia de un área eritematosa de la mucosa esofágica inferior, 3 cm por encima de la unión gastroesofágica, muestra epitelio cilíndrico con células caliciformes. ¿Qué alteración de la mucosa está más probablemente representada?","a":"Metaplasia intestinal (esófago de Barrett).","e":"Metaplasia = troca de um tipo de célula por outro, quase sempre por dano e reparo (aqui, refluxo). O epitélio escamoso do esôfago distal vira glandular. A displasia é frequente no epitélio metaplásico, mas nem todo epitélio metaplásico é displásico (slide 38 da Clase 11)."},{"p":"final24","n":18,"t":"mc","tema":"neo","q":"Se realiza una biopsia cervical cuyo estudio histológico muestra un carcinoma in situ con áreas de epitelio escamoso con formación de perlas córneas. El concepto de carcinoma in situ corresponde a una lesión que se caracteriza por:","o":["Ausencia de atipia marcada","Baja incidencia de metástasis","Membrana basal intacta","Crecimiento desordenado en todo el espesor epitelial"],"ok":[2],"w":["O carcinoma in situ tem atipia marcada; o que o define é a ausência de invasão.","Não é o critério que define o in situ; o que o separa do invasivo é a membrana basal preservada.","Lesão precursora não invasiva: as células atípicas não atravessaram a membrana basal.","A desordem em toda a espessura do epitélio também aparece no in situ, mas a prova marca a membrana basal intacta como a característica."]},{"p":"final24","n":20,"t":"mc","tema":"neo","q":"Una masa sólida en la pared uterina se corresponde con un leiomiosarcoma bien diferenciado. Ante este dato, podemos afirmar que se trata de una masa:","o":["Maligna, epitelial, no encapsulada","Benigna, derivada de varias capas germinales","Maligna, de origen mesenquimático","Benigna, de crecimiento lento, encapsulada"],"ok":[2],"w":["Maligno epitelial seria carcinoma; o leiomiossarcoma vem do músculo liso.","Benigno derivado de várias camadas germinativas seria um teratoma.","Sarcoma = maligno de origem mesenquimatosa (aqui, músculo liso). Se fosse epitelial, seria carcinoma.","Benigno, de crescimento lento e encapsulado seria o leiomioma, não o leiomiossarcoma."]},{"p":"final24","n":25,"t":"mc","tema":"neo","q":"Una mujer de 48 años se somete a un examen físico de rutina. Se palpa una masa no dolorosa de 4 cm de diámetro en la mama derecha. La masa parece fijada a la pared torácica. Se palpa otra masa no dolorosa de 2 cm en la axila izquierda. Una radiografía de tórax revela múltiples nódulos de 0,5 a 2 cm en ambos pulmones. ¿Cuál de las siguientes clasificaciones TNM indica mejor el estadio de su enfermedad?","o":["T1N1M0","T2N1M0","T4N1M1"],"ok":[2],"w":["Há metástases pulmonares, então M não pode ser M0, e o tumor está fixado à parede torácica.","Também M0; ignora os nódulos pulmonares bilaterais e a fixação à parede torácica.","T4 (massa fixada à parede torácica), N1 (gânglio axilar) e M1 (nódulos pulmonares = metástases à distância)."]},{"p":"final24","n":26,"t":"cita","tema":"neo","q":"¿Cuáles son los criterios que se usan para la estadificación de tumores?","a":"Tamaño de la lesión primaria; propagación en ganglios linfáticos; presencia o ausencia de metástasis.","e":"É o TNM: T (tamanho e extensão do primário), N (linfonodos regionais) e M (metástases à distância). Slide 60 da Clase 11."},{"p":"final24","n":27,"t":"comp","tema":"neo","q":"Acúmulo abundante de colágeno en la neoplasia:","a":"Desmoplasia.","e":"Estroma reativo com colágeno abundante, como no câncer de mama de consistência pétrea (escirro). Slide 4 da Clase 11."},{"p":"final24","n":"32b","t":"cita","tema":"neo","q":"Tipo de diseminación metastásica de un tumor pulmonar:","a":"Diseminación hematógena.","e":"Resposta da folha da prova. Na prova aparece duas vezes o número 32; esta é a segunda."},{"p":"p2_26","n":1,"t":"cita","tema":"nec","q":"2 patrones de necrosis en los que predomina la desnaturalización de proteínas:","a":"Necrosis coagulativa y gangrena seca.","e":"Desnaturalização conserva a arquitetura (coagulativa); a gangrena seca é coagulativa num membro isquêmico. Digestão enzimática seria licuefactiva e grasa.","nt":"Enunciado reconstruído a partir do gabarito oficial (página não fotografada). Gabarito 5º F, Fila 1, nº 1."},{"p":"p2_26","n":2,"t":"cita","tema":"apo","q":"2 cambios morfológicos de la apoptosis:","a":"Picnosis y cariorrexis (condensación y fragmentación de la cromatina); vesículas apoptóticas.","e":"A apoptose tem picnose e cariorrexe, mas NÃO cariólise (na correção ela insistiu nisso). Como a necrose também tem picnose e cariorrexe, junte um achado exclusivo: vesículas ou cuerpos apoptóticos.","nt":"Enunciado reconstruído a partir do gabarito oficial (página não fotografada). Gabarito 5º F, Fila 1, nº 2."},{"p":"p2_26","n":3,"t":"cita","tema":"acu","q":"2 características microscópicas de la composición de las placas ateroscleróticas estables:","a":"Cubierta fibrosa gruesa y mínima inflamación.","e":"Robbins: a placa estável tem cápsula fibrosa densa e espessa, pouca inflamação e núcleo ateromatoso pequeno. A vulnerável é o contrário: cápsula fina, muitos macrófagos, núcleo lipídico grande.","nt":"Gabarito 5º F, Fila 1, nº 3."},{"p":"p2_26","n":4,"t":"comp","tema":"acu","q":"Los macrófagos y las células musculares lisas cargadas de lipoproteínas oxidadas presentes en las placas ateromatosas, corresponden a las denominadas ______.","a":"Células espumosas.","e":"O citoplasma cheio de gotículas de colesterol fica espumoso ao microscópio óptico."},{"p":"p2_26","n":5,"t":"comp","tema":"apo","q":"Durante el periodo posparto, inicia un proceso de involución uterina cuyo mecanismo responsable de la reducción del tamaño y número de células musculares es un proceso de muerte por ______ (especificar).","a":"Apoptosis fisiológica.","e":"\"Especificar\" = escrever o adjetivo: só \"apoptosis\" fica incompleto. Involução de tecido dependente de hormônio após a retirada hormonal é apoptose fisiológica."},{"p":"p2_26","n":6,"t":"comp","tema":"nec","q":"Mujer de 71 años sufrió pérdida del conocimiento, no puede hablar ni mover el brazo derecho a causa de una oclusión de la arteria cerebral media izquierda que ha generado un área de necrosis ______.","a":"Licuefactiva.","e":"No sistema nervioso central a isquemia dá necrose licuefactiva (muito lipídio, enzimas da micróglia), e depois fica uma cavidade quística."},{"p":"p2_26","n":7,"t":"cita","tema":"acu","q":"2 factores de riesgo no modificables para el desarrollo de las placas ateromatosas:","a":"Edad avanzada y sexo masculino.","e":"Também valem antecedentes familiares e alterações genéticas. Escreva \"sexo masculino\", não \"homem\".","nt":"Gabarito 5º F, Fila 1, nº 7."},{"p":"p2_26","n":8,"t":"cita","tema":"acu","q":"2 factores de riesgo modificables para el desarrollo de las placas ateromatosas:","a":"Tabaquismo y síndrome metabólico.","e":"Também: hiperlipidemia (colesterol unido a lipoproteínas de baja densidad aumentado), hipertensión arterial, diabetes mellitus. No gabarito ela abreviou \"Sx metabólico\", mas o enunciado proíbe siglas: escreva \"síndrome metabólico\".","nt":"Gabarito 5º F, Fila 1, nº 8."},{"p":"p2_26","n":9,"t":"cita","tema":"nec","q":"Pareo · Necrosis fibrinoide (columna I, nº 9) corresponde a:","a":"Arteriolas renales en paciente con hipertensión maligna.","e":"Fibrinoide = dano vascular por imunocomplexos ou hipertensão maligna, com fibrina na parede.","nt":"Columna II: Muerte de neutrófilos posterior a una respuesta inflamatoria · Arteriolas renales en paciente con hipertensión maligna · Infección de hepatocitos por el virus de la hepatitis B · Endometrio adelgazado en una mujer post-menopáusica · Formación de abscesos pulmonares por acción de Staphylococcus aureus. Só 2 são corretas; dupla marcação anula."},{"p":"p2_26","n":10,"t":"cita","tema":"apo","q":"Pareo · Apoptosis patológica (columna I, nº 10) corresponde a:","a":"Infección de hepatocitos por el virus de la hepatitis B.","e":"Os linfócitos T citotóxicos matam os hepatócitos infectados (cuerpos de Councilman). A morte de neutrófilos após a inflamação é apoptose FISIOLÓGICA; endométrio pós-menopausa é atrofia; abscesso é necrose licuefactiva.","nt":"Columna II: Muerte de neutrófilos posterior a una respuesta inflamatoria · Arteriolas renales en paciente con hipertensión maligna · Infección de hepatocitos por el virus de la hepatitis B · Endometrio adelgazado en una mujer post-menopáusica · Formación de abscesos pulmonares por acción de Staphylococcus aureus. Só 2 são corretas; dupla marcação anula."},{"p":"p2_26","n":11,"t":"mc","tema":"nec","q":"¿En cuál de las siguientes situaciones es más probable que se produzca un infarto hemorrágico?","o":["Oclusión venosa secundaria a torsión testicular derecha","Disminución del flujo sanguíneo miocárdico por ateroesclerosis coronaria","Depósitos de inmunocomplejos en las paredes de las arteriolas renales","Infarto cerebral secundario a un tromboembolio originado en el ventrículo izquierdo"],"ok":[0],"w":["Oclusão VENOSA: o sangue entra e não sai → infarto rojo.","Oclusão arterial em órgão sólido → infarto blanco.","Isso é necrose fibrinoide, não infarto.","Cérebro: infarto com necrose licuefactiva por oclusão arterial."]},{"p":"p2_26","n":12,"t":"mc","tema":"apo","q":"¿Cuál de los siguientes aspectos histológicos tiene relación con la apoptosis y no con la necrosis?","o":["Citoplasma intensamente eosinófilo, con fragmentación del núcleo","Condensación de la cromatina nuclear en masas densas de formas y tamaños distintos","Aumento de la permeabilidad externa mitocondrial con liberación de citocromo C","Contenidos celulares que escapan a través de la membrana celular e inducen inflamación"],"ok":[2],"w":["Eosinofilia e cariorrexe também aparecem na necrose.","Condensação da cromatina (picnose) também ocorre na necrose; por isso não é exclusiva.","Liberação de citocromo C pela mitocôndria é exclusiva da via intrínseca da apoptose. É a do gabarito.","Membrana rota e inflamação = necrose."],"nt":"Gabarito oficial: C. A alternativa B descreve a apoptose no Robbins, mas a picnose também existe na necrose; ela quis o achado exclusivo."},{"p":"p2_26","n":13,"t":"mc","tema":"acu","q":"¿Cuál de los siguientes corresponde a un cambio agudo de las placas ateromatosas?","o":["Taponamiento cardíaco debido a hemorragia pericárdica","Rotura con formación de trombos, que pueden ocluir completamente la luz vascular","Atrofia isquémica de la media con pérdida de tejido elástico y formación de aneurismas","Crecimiento progresivo de la placa con estenosis y reducción de la perfusión arterial"],"ok":[1],"w":["Complicação de infarto/ruptura cardíaca, não da placa.","Rotura da placa → trombo: cambio agudo.","Aneurisma é complicação crônica (lenta) da placa.","Estenose progressiva é evolução crônica."]},{"p":"p2_26","n":14,"t":"mc","tema":"nec","q":"¿Qué hallazgo indicativo de necrosis podrás observar al microscopio electrónico?","o":["Vacuolas lipídicas transparentes en el citoplasma de las células","Presencia de masas de fosfolípidos llamadas figuras de mielina","Tumefacción de las mitocondrias y retículo endoplasmático","Rotura de la membrana lisosomal con liberación de enzimas digestivas"],"ok":[3],"w":["Cambio graso (lesão reversível, microscopio óptico).","As figuras de mielina aparecem também na lesão REVERSÍVEL; não indicam necrose (ela disse isso na correção).","Tumefação de organelas = lesão reversível.","Ruptura de membranas (lisossomal, plasmática) = irreversibilidade."]},{"p":"p2_26","n":15,"t":"mc","tema":"nec","q":"¿En cuál de las siguientes situaciones es posible observar focos de células grasas necróticas de contornos indefinidos, y presencia de jabones en forma de depósitos basófilos y amorfos?","o":["Diabetes mellitus","Esteatosis hepática","Infarto agudo de miocardio","Traumatismo de las mamas"],"ok":[3],"w":["Não causa necrose gordurosa.","Esteatose é acúmulo de gordura em célula viva, não necrose.","Infarto do miocárdio dá necrose coagulativa.","Necrose gordurosa traumática da mama: sabões de cálcio basófilos."]},{"p":"p2_26","n":16,"t":"mc","tema":"apo","q":"En el estudio de la enfermedad de Alzheimer, se observa que el mal plegamiento de proteínas [...] la muerte de las células con acumulaciones anómalas. ¿Cuál de las siguientes [...] muerte celular programada?","o":["Gen p53","Caspasas","Proteína Bcl2","Endonucleasa"],"ok":[1],"w":["O p53 detém o ciclo/induz apoptose no dano do ADN, mas não executa a morte.","As caspases executam a apoptose (morte programada).","BCL2 é antiapoptótica.","Endonuclease participa, mas a resposta esperada é caspasas."],"nt":"Trechos cortados na margem da foto."},{"p":"p2_26","n":17,"t":"mc","tema":"nec","q":"Mujer de 26 años con diagnóstico de endocarditis trombótica, presenta vegetaciones verrugosas pequeñas. Desarrolla dolor en el cuadrante superior [izquierdo]. [La tomografía] abdominal muestra una lesión del bazo en forma de cuña de 1,5 x 3 cm [...]. ¿Cuál de las siguientes anomalías celulares es más probable que se produzca en la lesión?","o":["Formación de abscesos","Necrosis fibrinoide","Infarto hemorrágico","Necrosis coagulativa"],"ok":[3],"w":["Só se o êmbolo fosse séptico.","Necrose de parede vascular, não do órgão.","Baço: órgão sólido com circulação terminal → infarto blanco.","Infarto em cunha de órgão sólido = necrose coagulativa."],"nt":"Trechos cortados na margem da foto."},{"p":"r26g","n":1,"t":"cita","tema":"acu","q":"Células inflamatorias presentes en las placas ateromatosas:","a":"Linfocitos T y macrófagos.","e":"Na correção: monócito que entra na íntima passa a se chamar macrófago; \"células espumosas\" é o macrófago que comeu colesterol. Células musculares lisas NÃO são inflamatórias (formam a cápsula fibrosa).","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Linfocitos T, Macrófagos\"."},{"p":"r26g","n":2,"t":"cita","tema":"acu","q":"Cambios patológicos (agudos) que pueden sufrir las placas ateromatosas:","a":"Rotura (ulceración o erosión), hemorragia y ateroembolia.","e":"A trombose NÃO é um cambio da placa: é consequência da rotura (ela frisou). Calcificação e necrose existem na placa, mas não estão na lista de cambios dela.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Rotura, Hemorragia, Ateroembolia\"."},{"p":"r26g","n":3,"t":"cita","tema":"nec","q":"2 condiciones que determinan que un órgano sufra un infarto hemorrágico (rojo):","a":"Doble circulación y tejido laxo o esponjoso.","e":"Também: oclusão VENOSA, reperfusão, congestão prévia. Oclusão arterial gera infarto blanco.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Doble circulación; tejido laxo o esponjoso\"."},{"p":"r26g","n":4,"t":"cita","tema":"apo","q":"2 características de la apoptosis (que la diferencian de la necrosis):","a":"Formación de cuerpos apoptóticos y ausencia de inflamación.","e":"Ela aceitou qualquer característica diferente da necrose: membrana íntegra, ativação de caspasas, morte programada. Cuidado: escrever só \"picnosis y cariorrexis\" não diferencia (a necrose também tem); diga que NÃO há cariólisis.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Formación de cuerpos apoptóticos; ausencia de inflamación (activación de caspasas, muerte programada)\"."},{"p":"r26g","n":5,"t":"cita","tema":"acu","q":"Alteraciones del colesterol que favorecen la formación de placas ateromatosas:","a":"Aumento del colesterol unido a lipoproteínas de baja densidad y disminución del colesterol unido a lipoproteínas de alta densidad.","e":"Quem inverteu (alta densidade aumentada) errou. Escreva os nomes por extenso.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Lipoproteína de baja densidad: ↑ colesterol LDL; ↓ colesterol HDL\"."},{"p":"r26g","n":6,"t":"comp","tema":"apo","q":"En una infección viral, los linfocitos T citotóxicos provocan la muerte de los hepatocitos mediante la activación de las enzimas denominadas ______.","a":"Caspasas.","e":"Primeiro identifique o tipo de morte (apoptose) e depois a enzima dela.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Caspasas\"."},{"p":"r26g","n":7,"t":"comp","tema":"acu","q":"Los factores de crecimiento estimulan la síntesis de matriz extracelular, en especial de colágeno, producido en las placas por las ______.","a":"Células musculares lisas.","e":"São elas que migram da média para a íntima e fabricam o colágeno da cápsula fibrosa.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Cél. musculares lisas\" (escreva sem abreviar)."},{"p":"r26g","n":8,"t":"comp","tema":"c7","q":"Los cuerpos de Russell en las células plasmáticas de un hombre de 60 años están llenos de ______.","a":"Inmunoglobulinas (anticuerpos).","e":"\"Proteínas\" é genérico e não vale. \"Inmunocomplejos\" está errado: imunocomplexo é anticorpo ligado a antígeno, e dentro do plasmócito o anticorpo ainda não encontrou antígeno.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Gabarito 5º G: \"Inmunoglobulinas\"."},{"p":"r26g","n":9,"t":"cita","tema":"c7","q":"Pareo · Cuerpos de psamoma corresponden a:","a":"Depósitos concéntricos laminados de calcio en un tumor papilar.","e":"Calcificação distrófica em tumores papilares (tireoide, ovário, meningioma).","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Opções lidas: glóbulos eosinófilos de proteína mal plegada en hepatocitos de un paciente con enfisema pulmonar (alfa-1-antitripsina) · depósitos concéntricos de calcio en un tumor papilar · marañas alargadas de filamentos en cerebros de enfermos de Alzheimer (ovillos neurofibrilares) · inclusión citoplasmática eosinófila de células hepáticas relacionada con el consumo de alcohol · calcio en la capa media de la arteria de un paciente de 80 años (esclerosis medial calcificada)."},{"p":"r26g","n":10,"t":"cita","tema":"c7","q":"Pareo · Cuerpos de Mallory corresponden a:","a":"Inclusión citoplasmática eosinófila de células hepáticas relacionada con el consumo de alcohol.","e":"Hialina de Mallory: filamentos intermediários (queratina) agregados no hepatócito.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Opções lidas: glóbulos eosinófilos de proteína mal plegada en hepatocitos de un paciente con enfisema pulmonar (alfa-1-antitripsina) · depósitos concéntricos de calcio en un tumor papilar · marañas alargadas de filamentos en cerebros de enfermos de Alzheimer (ovillos neurofibrilares) · inclusión citoplasmática eosinófila de células hepáticas relacionada con el consumo de alcohol · calcio en la capa media de la arteria de un paciente de 80 años (esclerosis medial calcificada)."},{"p":"r26g","n":11,"t":"mc","tema":"nec","q":"¿Qué cambio podrá observar al microscopio electrónico en la necrosis?","o":["Rotura de la membrana lisosomal con liberación de enzimas digestivas","Presencia de masas de fosfolípidos llamadas figuras de mielina","Formación generalizada de vesículas en la membrana celular","[Achado visto ao microscopio óptico: citoplasma intensamente eosinófilo e alterações nucleares]"],"ok":[0],"w":["Correta: ruptura de membranas = necrose.","Também aparecem na lesão celular reversível; não são exclusivas.","Vesículas na membrana = lesão reversível (e apoptose).","É achado do microscópio óptico, não do eletrônico."],"nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes."},{"p":"r26g","n":12,"t":"mc","tema":"acu","q":"¿Cuál de los siguientes es un factor de riesgo adquirido para el desarrollo de las placas ateromatosas?","o":["Uso de anticonceptivos orales","Presión arterial menor a 120/80 milímetros de mercurio","Colesterol unido a lipoproteínas de alta densidad mayor a 45 miligramos por decilitro","Glucemia en ayunas mayor a 200 miligramos por decilitro"],"ok":[3],"w":["Não está na lista de fatores da aula.","Pressão normal.","Lipoproteína de alta densidade alta protege.","Glicemia > 200 = diabetes mellitus, fator adquirido."],"nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. A opção A não foi audível."},{"p":"r26g","n":13,"t":"mc","tema":"apo","q":"¿Cuál de los siguientes casos clínicos se asocia con apoptosis fisiológica?","o":["Disminución del flujo sanguíneo miocárdico por ateroesclerosis coronaria","Paciente con enfermedad de Parkinson","[Opção com liberação de conteúdo e inflamação: necrosis]","Cambios por pérdida de estímulos hormonales después de la menopausia"],"ok":[3],"w":["Isquemia = necrose.","Proteína mal dobrada = apoptose PATOLÓGICA.","Necrose.","Retirada hormonal = apoptose fisiológica."],"nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes."},{"p":"r26g","n":14,"t":"mc","tema":"nec","q":"Mujer de 68 años perdió el conocimiento de repente y al despertarse una hora después no podía hablar ni mover el brazo derecho. A los dos meses, una tomografía de cráneo muestra una gran área quística en el lóbulo parietal izquierdo. ¿Cuál de los siguientes procesos patológicos es más probable que haya tenido lugar en el cerebro?","o":["Infiltrado neutrofílico con restos necróticos licuados","Necrosis caseosa con calcificación","Granuloma con células gigantes","Depósitos de inmunocomplejos"],"ok":[0],"w":["Correta: necrose licuefactiva (a questão não diz o nome, descreve).","Tuberculose.","Granuloma = tuberculose.","Necrose fibrinoide."],"nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes."},{"p":"r26g","n":15,"t":"cita","tema":"c7","q":"Paciente de 65 años con dolor en la mano izquierda, depósitos de calcio en las articulaciones y calcemia de 15,4 miligramos por decilitro (normal 8,5 a 10,5). Tipo de calcificación y causa más probable:","a":"Calcificación metastásica por hipercalcemia (causa más probable: hiperparatiroidismo).","e":"Cálcio sérico alto = metastásica. Ela lembrou paratireoide, osso, intestino e vitamina D. Leia o enunciado com atenção: o envelhecimento normal e a doença aterosclerótica dão calcificação distrófica.","nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. As alternativas não foram todas audíveis; transformada em resposta curta."},{"p":"r26g","n":16,"t":"mc","tema":"nec","q":"Mujer de 25 años con lupus eritematoso sistémico, anticuerpos en sangre y depósitos de inmunocomplejos en una biopsia renal. ¿Qué alteración es probable encontrar en los vasos sanguíneos del riñón?","o":["Necrosis caseosa","Necrosis fibrinoide","Necrosis licuefactiva","Necrosis grasa"],"ok":[1],"w":["Tuberculose.","Imunocomplexos + fibrina na parede = fibrinoide.","Cérebro/abscesso.","Pâncreas/mama."],"nt":"Enunciado da correção em aula (gravação transcrita); trechos inaudíveis entre colchetes. Alternativas além da B reconstruídas."},{"p":"p1g26","n":1,"t":"cita","tema":"les","q":"Células de tejidos estables (quiescentes):","a":"Células parenquimatosas del hígado, del riñón y de la tiroides; células musculares lisas y fibroblastos.","e":"Saem do repouso e se dividem quando há perda (hepatectomia).","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":2,"t":"cita","tema":"les","q":"2 enzimas activadas por el aumento del calcio intracelular:","a":"Fosfolipasas y endonucleasas.","e":"Também proteasas e ATPasas.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":3,"t":"cita","tema":"les","q":"Métodos de observación de las lesiones:","a":"Microscopio óptico y microscopio electrónico (también inmunofluorescencia).","e":"Escreva o nome inteiro do microscópio.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":4,"t":"cita","tema":"les","q":"Cambios macroscópicos de la tumefacción celular:","a":"Aumento del tamaño, aumento del peso, aumento de la turgencia y palidez del órgano.","e":"Lesão reversível por entrada de água.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":5,"t":"cita","tema":"les","q":"Hallazgo microscópico de la tumefacción celular:","a":"Vacuolas transparentes en el citoplasma de las células.","e":"Degeneração hidrópica.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":6,"t":"cita","tema":"les","q":"Producto de la glucólisis anaerobia que disminuye el pH en la hipoxia:","a":"Ácido láctico.","e":"Sem oxigênio a célula usa glicólise anaeróbia.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":7,"t":"cita","tema":"les","q":"Adaptación del ventrículo izquierdo en la hipertensión arterial:","a":"Hipertrofia concéntrica.","e":"Sobrecarga de pressão.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":8,"t":"cita","tema":"c7","q":"Coloración que identifica el amiloide:","a":"Rojo Congo.","e":"Verde manzana na luz polarizada.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":9,"t":"cita","tema":"les","q":"3 coloraciones especiales para mucinas e hidratos de carbono:","a":"Mucicarmín, ácido periódico de Schiff y azul alcián.","e":"Ela escreveu \"ácido periódico de Schiff\" por extenso.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":10,"t":"cita","tema":"les","q":"2 causas de hipertrofia cardíaca por sobrecarga de presión:","a":"Hipertensión arterial y estenosis valvular (aórtica o mitral).","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":11,"t":"cita","tema":"les","q":"2 consecuencias de la lesión celular por hipoxia:","a":"Activación de endonucleasas y disminución del pH intracelular.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":12,"t":"cita","tema":"les","q":"Procedimiento de obtención de tejido de un paciente vivo para diagnóstico:","a":"Biopsia.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":13,"t":"cita","tema":"les","q":"Tipo de hiperplasia del hígado restante tras una hepatectomía parcial:","a":"Hiperplasia fisiológica compensadora.","e":"Escreva os dois adjetivos.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":14,"t":"cita","tema":"les","q":"Ion cuyo aumento intracelular activa fosfolipasas, proteasas y endonucleasas:","a":"Calcio.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":15,"t":"cita","tema":"les","q":"2 patrones de lesión celular reversible al microscopio óptico:","a":"Edema celular y cambio graso (esteatosis).","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":16,"t":"cita","tema":"les","q":"3 cambios ultraestructurales (microscopio electrónico) de la lesión celular reversible:","a":"Figuras de mielina, vesículas en la membrana plasmática y tumefacción de las organelas.","e":"Por isso na 2ª parcial as figuras de mielina NÃO indicam necrose.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":17,"t":"cita","tema":"les","q":"2 microorganismos identificables con coloraciones especiales en pacientes inmunodeprimidos:","a":"Cryptococcus neoformans y Pneumocystis jirovecii.","e":"Nome científico completo, gênero e espécie.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":18,"t":"cita","tema":"les","q":"Causas de hipertrofia cardíaca por sobrecarga de volumen o miocardiopatía:","a":"Enfermedad de Chagas e insuficiencia mitral.","e":"No gabarito: \"Enf. de Chagas\"; escreva \"enfermedad\".","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":19,"t":"cita","tema":"les","q":"Consecuencias de la disminución del ATP en la hipoxia:","a":"Activación de proteasas, disminución del ATP y desprendimiento de los ribosomas.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":20,"t":"cita","tema":"les","q":"Método que estudia células descamadas espontáneamente o por raspado:","a":"Citología exfoliativa.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":21,"t":"cita","tema":"les","q":"Tipo de hiperplasia del endometrio por exceso de estrógenos:","a":"Hiperplasia patológica.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":22,"t":"cita","tema":"les","q":"Ion que entra en la célula con agua cuando falla la bomba de sodio y potasio:","a":"Sodio.","e":"Resposta oficial.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":23,"t":"cita","tema":"acu","q":"Características macroscópicas del hígado con esteatosis:","a":"Peso aumentado, tamaño aumentado y color amarillo.","e":"Literal do gabarito 5º G.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"p1g26","n":24,"t":"cita","tema":"acu","q":"Hallazgo microscópico de la esteatosis:","a":"Vacuolas lipídicas transparentes.","e":"Literal do gabarito 5º G.","nt":"Gabarito oficial da 1ª parcial 2026; enunciado reconstruído (página não fotografada)."},{"p":"f24t","n":2,"t":"cita","tema":"cro","q":"Dos anomalías por formación excesiva de componentes que participan en la reparación de los tejidos:","a":"Cicatriz hipertrófica y queloide.","e":"Excesso de colágeno: a hipertrófica fica elevada dentro dos limites da ferida; o queloide passa das bordas e não regride. Excrecências carnosas (excesso de tecido de granulação) também são excesso de reparo.","nt":"Na folha: \"Anomalías por formación excesiva…\", com duas linhas (a, b). A transcrição responde \"cicatrices hipertróficas y cicatrices queloides\".","fc":1},{"p":"f24t","n":3,"t":"cita","tema":"cro","q":"Dos enfermedades granulomatosas no necrosantes:","a":"Sarcoidosis y enfermedad de Crohn (la lepra también es correcta).","e":"Qualquer duas de três: sarcoidose, doença de Crohn e lepra dão granulomas não caseosos (o de corpo estranho também não necrosa). O slide dela destaca Crohn e sarcoidose.","nt":"Na folha são duas linhas (a, b); a transcrição lista as três, e qualquer duas servem.","fc":1},{"p":"f24t","n":4,"t":"cita","tema":"cro","q":"Dos enfermedades granulomatosas necrosantes:","a":"Tuberculosis y sífilis.","e":"Tuberculose: necrose caseosa central. Sífilis: goma, com células centrais necróticas que conservam o contorno.","nt":"Só na transcrição digitada; não aparece na foto da folha.","fc":1},{"p":"f24t","n":9,"t":"comp","tema":"les","q":"La proliferación del epitelio glandular endometrial en una mujer embarazada es un ejemplo de ________ que ocurre como respuesta a estímulos hormonales.","a":"Hiperplasia fisiológica.","e":"Estímulo hormonal normal = hiperplasia fisiológica hormonal. Por excesso de estrogênio seria patológica.","nt":"Na foto da folha é a questão 7.","fc":1},{"p":"f24t","n":10,"t":"comp","tema":"cro","q":"Las células ________ presentan un citoplasma granular rosado con bordes celulares no diferenciados que corresponden a células derivadas de ________.","a":"Epitelioides; macrófagos activados.","e":"A célula epitelioide é o macrófago ativado do granuloma: citoplasma granular rosado e limites pouco definidos.","nt":"Na foto da folha é a questão 8.","fc":1},{"p":"f24t","n":13,"t":"cita","tema":"cro","q":"Hombre de 43 años presenta tos crónica y fiebre de 1 mes de evolución. Una muestra de biopsia transbronquial revela infiltrados intersticiales con linfocitos, células plasmáticas y macrófagos activados. ¿Cuál de los mediadores químicos es más importante en la activación de los macrófagos?","a":"Interferón gamma.","e":"Inflamação crônica (mononucleares). O linfócito T colaborador 1 libera interferón gamma, que ativa o macrófago pela via clássica.","nt":"Na foto da folha é a questão 11, com a resposta \"Interferón γ\". Escreva por extenso.","fc":1},{"p":"f24t","n":15,"t":"mc","tema":"cro","q":"En el proceso de curación, una incisión quirúrgica limpia no infectada es una lesión que se cura por:","o":["Primera intención","Segunda intención","Regeneración epitelial","Sin fibrosis"],"ok":[0],"w":["Incisão limpa, sem infecção e com bordas aproximadas: primeira intenção.","Segunda intenção é para perdas extensas: feridas grandes, abscessos, úlceras, infartos.","A epiderme regenera, mas a derme cicatriza; a cura não é só regeneração.","Mesmo a primeira intenção deixa uma pequena cicatriz de colágeno."],"nt":"Na foto da folha é a questão 14.","fc":1},{"p":"f24t","n":16,"t":"mc","tema":"cro","q":"Son características histológicas de la inflamación crónica:","o":["Presencia de neutrófilos y macrófagos","Aumento de permeabilidad vascular","Vasodilatación y estasis sanguínea","Proliferación de pequeños vasos sanguíneos"],"ok":[3],"w":["Neutrófilo é a marca da aguda; na crônica predominam mononucleares.","Aumento de permeabilidade é mudança vascular da aguda.","Vasodilatação e estase são da aguda.","Angiogenia faz parte da tentativa de cura da crônica; é a única mudança vascular dela."],"nt":"Na foto da folha é a questão 15 (\"histológicas\"); a transcrição escreveu \"biológicas\".","fc":1},{"p":"f24t","n":19,"t":"mc","tema":"les","q":"De acuerdo a la capacidad de proliferación, las células de la médula ósea se clasifican como:","o":["Lábiles","Estables","Permanentes","Transitorios"],"ok":[0],"w":["Medula óssea, linfonodos e epitélios de pele e mucosas se dividem continuamente.","Estáveis ficam em repouso e só se dividem depois de lesão: fígado, rim, pâncreas, endotélio, fibroblastos, músculo liso.","Permanentes não se dividem: neurônios, músculo cardíaco e esquelético.","\"Transitorios\" não é categoria de proliferação."],"nt":"Na foto da folha é a questão 18.","fc":1},{"p":"f24t","n":22,"t":"mc","tema":"les","q":"¿Qué cambios podríamos observar en un corazón hipertrofiado?","o":["Aumento del peso del órgano debido a nuevas células","Mayor tamaño celular debido a la acumulación de líquido intracitoplasmático","Aumento de proteínas contráctiles intracitoplasmáticas","Menor consumo de oxígeno para realizar el mismo trabajo que el corazón normal"],"ok":[2],"w":["Células novas seria hiperplasia; o miocárdio é permanente e só hipertrofia.","Água dentro da célula é tumefação celular (lesão reversível), não adaptação.","Slide: \"más síntesis de proteínas y aumento de número de miofilamentos\".","Há mais músculo para nutrir e os capilares não acompanham; o coração hipertrofiado fica mais sujeito à isquemia."],"nt":"Na foto da folha é a questão 21.","fc":1},{"p":"f24t","n":"22b","t":"mc","tema":"cro","q":"Hombre de 24 años con apendicitis aguda se somete a la extirpación quirúrgica del apéndice inflamado. La incisión se sutura. La microscopía óptica muestra un corte de la zona con tinción tricrómica: el colágeno abundante está teñido de azul. ¿Cuánto tiempo después de la cirugía sería más probable observar esto?","o":["1 día","4–5 días","1 mes"],"ok":[2],"w":["No 1º dia há coágulo e neutrófilos; ainda não há colágeno.","Aos 3–5 dias o achado é tecido de granulação (vasos no máximo, fibroblastos ativos), com pouco colágeno maduro. Na foto essa opção está circulada por um aluno.","O colágeno se acumula na 2ª semana e a cicatriz está formada na 4ª: colágeno denso, que o tricrômico cora de azul."],"nt":"Sem gabarito oficial no material: a transcrição repete o número 22 e não marca resposta, e na foto (questão 22) \"4–5 días\" está circulado com a nota \"por causa do tejido de granulación\". A resposta aqui segue a cronologia do Robbins (cap. 3).","fc":1},{"p":"f24t","n":23,"t":"mc","tema":"les","q":"Hombre de 71 años tiene dificultad para orinar. Su retención urinaria provoca numerosos viajes al baño. En el tacto rectal la próstata está agrandada de forma difusa. ¿Cuál de los siguientes representa un cambio patológico que conduce al problema de este hombre?","o":["Displasia in situ","Hipertrofia mioepitelial","Hiperplasia glandular"],"ok":[2],"w":["Displasia é lesão precursora de câncer; não explica um aumento difuso.","Não é a adaptação da próstata do idoso.","Hiperplasia prostática benigna: hiperplasia glandular por ação dos andrógenos."],"nt":"Na foto da folha é a questão 24.","fc":1},{"p":"f24t","n":28,"t":"cita","tema":"cro","q":"Citar dos características de la inflamación crónica:","a":"Infiltración por células mononucleares (macrófagos, linfocitos y células plasmáticas); intentos de curación (angiogenia: proliferación de pequeños vasos sanguíneos).","e":"Slide dela: 1) infiltrado de células mononucleares; 2) destruição dos tecidos; 3) tentativas de cura por angiogenia e fibrose. A transcrição respondeu com a 1ª e a 3ª.","nt":"Só na transcrição digitada.","fc":1},{"p":"f24t","n":31,"t":"cita","tema":"cro","q":"Cite las diferencias del tejido de granulación y cicatriz:","a":"Tejido de granulación: angiogénesis, colágeno tipo III, fibroblastos activos; cicatriz: desvascularización, colágeno tipo I, fibroblastos inactivos.","e":"Granulação é o tecido jovem do reparo (3–5 dias): muitos vasos novos e fibroblastos trabalhando. A cicatriz é madura, pálida e avascular.","nt":"Só na transcrição digitada.","fc":1},{"p":"f24t","n":"33b","t":"cita","tema":"cro","q":"Anomalías causadas por deficiencias de la cicatrización:","a":"Úlceras y dehiscencia de la herida.","e":"Robbins: pouco tecido de granulação ou colágeno mal remodelado levam à deiscência (a ferida se abre) ou à ulceração.","nt":"Só na transcrição digitada, que repete o número 33 (\"deformidades da cicatrização\").","fc":1},{"p":"f24t","n":35,"t":"cita","tema":"cro","q":"Caso clínico: úlceras y abscesos cicatrizan por:","a":"Segunda intención.","e":"Perda extensa de tecido: mais inflamação, muito tecido de granulação e contração por miofibroblastos.","nt":"Só na transcrição digitada.","fc":1},{"p":"par1","n":5,"t":"cita","tema":"les","q":"En una hepatectomía parcial, se inicia un estímulo por factores de crecimiento, lo que conduce a un aumento de tamaño del hígado. Proceso adaptativo que corresponde a:","a":"Hiperplasia fisiológica compensatoria.","e":"O hepatócito é estável: volta a se dividir quando o fígado perde massa. Slide: hiperplasia fisiológica compensadora (hepatectomia parcial).","fc":1},{"p":"par1","n":13,"t":"mc","tema":"les","q":"Los tejidos que tienen capacidad de crecimiento hiperplásico y se clasifican como lábiles corresponden a:","o":["Músculo esquelético, túbulos renales y ácinos pancreáticos","Células de la médula ósea, ganglios linfáticos y epidermis","Tejido de granulación, cerebro y médula suprarrenal","Folículos tiroideos, células endoteliales y hepatocitos"],"ok":[1],"w":["Músculo esquelético é permanente; túbulos renais e ácinos pancreáticos são estáveis.","Slide dela: lábeis = epitélio de pele e mucosas, medula óssea e linfonodos.","Tecido de granulação não é categoria; cérebro (neurônios) é permanente.","São todas estáveis."],"fc":1},{"p":"par1","n":17,"t":"mc","tema":"les","q":"El engrosamiento de la pared ventricular cardíaca en un paciente con valvulopatía aórtica es un ejemplo de ______ y ocurre por ______:","o":["Hipertrofia patológica, aumento de volumen celular","Hiperplasia patológica, aumento de volumen celular","Hipertrofia fisiológica, aumento de número de células","Hiperplasia compensatoria, aumento del número de células"],"ok":[0],"w":["Sobrecarga hemodinâmica crônica (valvopatia) → hipertrofia patológica: células maiores.","Hiperplasia é aumento do número; e o miocárdio é permanente.","Valvopatia não é estímulo fisiológico, e hipertrofia não aumenta o número de células.","O miocárdio não faz hiperplasia."],"fc":1},{"p":"p1c","n":11,"t":"cita","tema":"les","q":"Mujer de 53 años, sin antecedentes de interés, va a su médico para una revisión rutinaria; presenta una presión arterial de 150/95 y hallazgos electrocardiográficos sugestivos de cardiomegalia.","a":"Síntesis de proteínas aumentada.","e":"Hipertensão → sobrecarga de pressão → hipertrofia do ventrículo esquerdo: mais proteínas contráteis e miofilamentos, sem divisão celular.","nt":"Questão de quadro de opções: falla de bomba de sodio y potasio, síntesis de proteínas aumentadas, piroptosis, presencia de citocromo c, colesterol LDL bajo, gangrena seca, necrosis caseosa, división celular aumentada.","fc":1},{"p":"p1c","n":13,"t":"mc","tema":"les","q":"Los tejidos que tienen capacidad de crecimiento hiperplásico y se clasifican como estables:","o":["Músculo esquelético, túbulos renales y ganglios linfáticos","Músculo cardíaco, ácinos pancreáticos y epidermis","Tejido cicatricial, cerebro y médula suprarrenal","Folículos tiroideos, células endoteliales y hepatocitos"],"ok":[3],"w":["Músculo esquelético é permanente e linfonodo é lábil.","Músculo cardíaco é permanente e epiderme é lábil.","Tecido cicatricial não é categoria; cérebro é permanente.","Slide dela: estáveis = tireoide, células endoteliais, fígado (e rim, pâncreas, fibroblastos, músculo liso)."],"nt":"A transcrição não marca a resposta; a certa sai do slide de hiperplasia (células estables).","fc":1},{"p":"par1r","n":13,"t":"mc","tema":"les","q":"Los tejidos que tienen la capacidad de crecimiento hiperplásico y se clasifican como estables corresponden a:","o":["Músculo esquelético, ácinos pancreáticos","Músculo liso, hepatocitos","Células de la médula ósea, epidermis","Tejido de granulación, cerebro"],"ok":[1],"w":["Músculo esquelético é permanente.","Músculo liso e hepatócito são estáveis.","Medula óssea e epiderme são lábeis.","Tecido de granulação não é categoria; cérebro é permanente."],"fc":1},{"p":"par1r","n":18,"t":"mc","tema":"les","q":"Una mujer de 22 años está embarazada. En la ecografía fetal de 13 semanas el útero mide 7 × 4 × 3 cm. En el parto a término, el útero mide 34 × 18 × 12 cm. ¿Cuál de los siguientes procesos celulares ha contribuido al incremento de tamaño del útero?","o":["Hipertrofia del músculo liso uterino","Hipertrofia del estroma endometrial","Hiperplasia del endotelio vascular","Hiperplasia atípica del endometrio"],"ok":[0],"w":["Slide dela: hipertrofia fisiológica do útero (fibras musculares lisas) por estímulo estrogênico.","O que cresce é o miométrio, não o estroma endometrial.","Não é o que aumenta o órgão.","Hiperplasia atípica é lesão patológica."],"fc":1}],"paginas":[{"g":"P2 · Turma C","sub":"Transcrição digitada","pages":[{"p":79,"w":1200,"h":1532},{"p":80,"w":1200,"h":1532},{"p":81,"w":1200,"h":1532},{"p":82,"w":1200,"h":1532}]},{"g":"P2 · Turma D","sub":"Folha digitada","pages":[{"p":90,"w":1200,"h":1697},{"p":91,"w":1200,"h":1697},{"p":92,"w":1200,"h":1697},{"p":93,"w":1200,"h":1697},{"p":94,"w":1200,"h":1697},{"p":95,"w":1200,"h":1697}]},{"g":"P2 · fotos","sub":"Duas provas na mesma página","pages":[{"p":97,"w":1200,"h":1696}]},{"g":"Regularización 2024","sub":"Foto, Turma C","pages":[{"p":5,"w":1200,"h":1600}]},{"g":"Recuperatoria 09/06/2023","sub":"Fotos","pages":[{"p":96,"w":1200,"h":1696},{"p":98,"w":1200,"h":1696}]},{"g":"Examen Final 21/02/2024","sub":"Fotos e transcrição","pages":[{"p":1,"w":1200,"h":1535},{"p":2,"w":1200,"h":1333},{"p":3,"w":1200,"h":1656},{"p":4,"w":1200,"h":1381},{"p":104,"w":1200,"h":1532},{"p":105,"w":1200,"h":1532},{"p":106,"w":1200,"h":1532},{"p":107,"w":1200,"h":1532},{"p":108,"w":1200,"h":1532},{"p":109,"w":1200,"h":1532},{"p":110,"w":1200,"h":1532}]},{"g":"1º Parcial","sub":"Fotos anotadas e folha digitada","pages":[{"p":8,"w":1200,"h":1751},{"p":9,"w":1200,"h":1900},{"p":10,"w":1200,"h":1759},{"p":11,"w":1200,"h":1732},{"p":12,"w":1200,"h":411},{"p":7,"w":1200,"h":1252},{"p":99,"w":1200,"h":1698},{"p":100,"w":1200,"h":1698},{"p":101,"w":1200,"h":1698},{"p":102,"w":1200,"h":1698},{"p":103,"w":1200,"h":1698}]},{"g":"1º Parcial · Recuperación","sub":"Fotos anotadas e folha digitada","pages":[{"p":16,"w":1200,"h":1737},{"p":17,"w":1200,"h":1784},{"p":18,"w":1200,"h":1752},{"p":87,"w":1200,"h":1698},{"p":88,"w":1200,"h":1698},{"p":89,"w":1200,"h":1698}]},{"g":"P1 · Turma C","sub":"Fotos anotadas e transcrição","pages":[{"p":13,"w":1200,"h":1750},{"p":14,"w":1200,"h":1809},{"p":15,"w":1200,"h":1776},{"p":83,"w":1200,"h":1698},{"p":84,"w":1200,"h":1698},{"p":85,"w":1200,"h":1698},{"p":86,"w":1200,"h":1698}]},{"g":"2ª parcial 2026","sub":"Prova 5º F (Fila 1) e gabaritos 5º F e 5º G","pages":[{"p":111,"w":1200,"h":1487},{"p":112,"w":1200,"h":1721},{"p":113,"w":1200,"h":2522},{"p":114,"w":1200,"h":874}]},{"g":"1ª parcial 2026","sub":"Gabaritos oficiais 5º F e 5º G","pages":[{"p":115,"w":1200,"h":1806},{"p":116,"w":1200,"h":1819},{"p":117,"w":1200,"h":1667}]}],"orgs":[{"g":"Mapa geral","h":["<h4 class=\"mm\">Mapa da 2ª parcial</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: LESIÓN CELULAR Y RESPUESTA\"><div class=\"org-root\">LESIÓN CELULAR Y RESPUESTA</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Necrosis<small>muerte celular accidental</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Lesión <b>irreversible</b></li><li>Membrana se rompe → <b>inflamación</b></li><li>Desnaturalización o digestión enzimática</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>6 patrones + ejemplo</li><li>Picnosis, cariorrexis, cariólisis</li><li>Infarto rojo × blanco</li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Apoptosis<small>muerte programada</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Activa, con <b>caspasas</b> y endonucleasas</li><li>Membrana íntegra → <b>sin inflamación</b></li><li>Cuerpos apoptóticos fagocitados</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>Fisiológica × patológica</li><li>Vía intrínseca (BCL2, citocromo C)</li><li>Vía extrínseca (Fas, TNFR1)</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Acumulación intracelular<small>lípidos y glucógeno</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Sustancia que la célula no metaboliza</li><li><b>Triglicéridos</b> → esteatosis</li><li><b>Colesterol</b> → aterosclerosis, xantomas</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>Células espumosas</li><li>Factores de riesgo</li><li>Complicaciones de la placa</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Necrosis</span><span style=\"background:#7a3fe0\">Apoptosis</span><span style=\"background:#a16207\">Acumulación</span></div><div class=\"org-note\">A necrose e a acumulação de colesterol <b>disparam</b> inflamação; a apoptose não. Esse é o fio que liga os 3 temas.</div></div>"]},{"g":"Necrosis","h":["<h4 class=\"mm\">Da lesão à morte celular</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ESTÍMULO LESIVO\"><div class=\"org-root\">ESTÍMULO LESIVO</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#15803d;--cs:#dcfce7\"><div class=\"org-head\">Lesión reversible<small>se retira el estímulo → vuelve a lo normal</small></div><div class=\"org-leaf\"><h5>Cambios</h5><ul><li><b>Tumefacción celular</b> (hidrópica)</li><li><b>Cambio graso</b></li><li>Ampollas en la membrana</li><li>Mitocondrias hinchadas, RE dilatado</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Lesión irreversible<small>punto de no retorno</small></div><div class=\"org-leaf\"><h5>3 fenómenos</h5><ul><li>No recupera la <b>función mitocondrial</b></li><li>Pérdida de estructura y función de las <b>membranas</b></li><li>Pérdida de la integridad del <b>ADN y la cromatina</b></li></ul></div><div class=\"org-leaf\"><h5>Ca²⁺ intracelular activa</h5><ul><li><b>Fosfolipasas</b> → membrana</li><li><b>Proteasas</b> → citoesqueleto</li><li><b>Endonucleasas</b> → núcleo</li><li>ATPasas → menos ATP</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Necrosis<small>muerte accidental</small></div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Siempre <b>patológica</b></li><li>Célula <b>aumenta</b> de tamaño</li><li>Rotura de membrana</li><li><b>Induce inflamación</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Apoptosis<small>muerte programada</small></div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Fisiológica o patológica</li><li>Célula se <b>encoge</b></li><li>Membrana <b>íntegra</b></li><li><b>Sin inflamación</b></li></ul></div></div></div></div>","<h4 class=\"mm\">Morfologia da necrose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: CAMBIOS MORFOLÓGICOS\"><div class=\"org-root\">CAMBIOS MORFOLÓGICOS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Microscopio óptico<small>citoplasma</small></div><div class=\"org-leaf\"><h5>Citoplasma</h5><ul><li><b>Aumento de eosinofilia</b> (pérdida de ARN, proteínas desnaturalizadas)</li><li>Aspecto vítreo, vacuolado</li><li>Figuras de mielina</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Núcleo<small>3 patrones</small></div><div class=\"org-leaf\"><h5>Picnosis</h5><ul><li>Núcleo <b>encogido</b> e hipercromático</li></ul></div><div class=\"org-leaf\"><h5>Cariorrexis</h5><ul><li>Núcleo <b>fragmentado</b></li></ul></div><div class=\"org-leaf\"><h5>Cariólisis</h5><ul><li>Basofilia nuclear <b>se desvanece</b> (ADNasa)</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Microscopio electrónico<small>irreversibilidad</small></div><div class=\"org-leaf\"><h5>Hallazgos</h5><ul><li><b>Rotura de membrana</b> plasmática y de organelas</li><li><b>Figuras de mielina</b></li><li>Densidades amorfas en mitocondrias</li></ul></div></div></div></div>","<h4 class=\"mm\">Organograma dos padrões de necrose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: NECROSIS\"><div class=\"org-root\">NECROSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Desnaturalización de proteínas<small>la arquitectura se conserva</small></div><div class=\"org-leaf\"><h5>Coagulativa</h5><ul><li><b>Isquemia</b> (excepto cerebro)</li><li>Infarto en <b>cuña</b>: IAM, riñón, bazo</li><li>Células \"fantasma\" eosinófilas</li><li>Infarto blanco</li></ul></div><div class=\"org-leaf\"><h5>Gangrena seca</h5><ul><li>Miembro sin infección</li><li>Congelación, isquemia</li><li>Patrón coagulativo</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Digestión enzimática<small>el tejido se licúa</small></div><div class=\"org-leaf\"><h5>Licuefactiva</h5><ul><li><b>Cerebro</b> (ACV, arteria cerebral media) → espacios quísticos</li><li><b>Abscesos</b>: bacterias piógenas, <i>S. aureus</i></li><li>Pus: enzimas de neutrófilos</li></ul></div><div class=\"org-leaf\"><h5>Grasa</h5><ul><li><b>Pancreatitis</b> aguda</li><li>Lipasas → ácidos grasos + Ca²⁺</li><li><b>Saponificación</b>: manchas blanco \"tiza\"</li></ul></div><div class=\"org-leaf\"><h5>Gangrena húmeda</h5><ul><li>Gangrena + <b>infección bacteriana</b></li><li>DM + pie negro + exudado</li><li>Patrón licuefactivo</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Mixta<small>coagulativa + licuefactiva</small></div><div class=\"org-leaf\"><h5>Caseosa</h5><ul><li><b>Tuberculosis</b></li><li>Aspecto de \"queso\", blanco amarillento</li><li><b>Granuloma</b>: células epitelioides, gigantes de <b>Langhans</b>, linfocitos</li><li>MO: material amorfo, granular, rosado</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Vascular inmune<small>pared de los vasos</small></div><div class=\"org-leaf\"><h5>Fibrinoide</h5><ul><li>Complejos Ag-Ac + fibrina en la pared</li><li><b>LES</b>, vasculitis, PAN</li><li>HTA maligna</li><li>Nódulo reumatoide</li></ul></div><div class=\"org-leaf\"><h5>Calcificación distrófica</h5><ul><li>Ca²⁺ en tejido <b>necrótico</b></li><li>Calcemia <b>normal</b></li><li>Placas de ateroma, válvulas</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Desnaturalización: coagulativa, gangrena seca</span><span style=\"background:#c2410c\">Digestión: licuefactiva, grasa, gangrena húmeda</span></div><div class=\"org-note\">Pergunta clássica dela: <b>cite 2 por desnaturalização</b> (coagulativa e gangrena seca) e <b>2 por digestão enzimática</b> (licuefativa e grasa).</div></div>","<h4 class=\"mm\">Infarto rojo × blanco</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: INFARTO\"><div class=\"org-root\">INFARTO</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Infarto blanco<small>anémico</small></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li>Oclusión <b>arterial</b></li><li>Órganos <b>sólidos</b> con circulación terminal</li><li><b>Corazón, bazo, riñón</b></li><li>Forma de cuña · necrosis coagulativa</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Infarto rojo<small>hemorrágico</small></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li>Oclusión <b>venosa</b> (torsión ovárica, testicular)</li><li>Tejidos <b>laxos</b></li><li><b>Doble circulación</b>: pulmón, hígado</li><li>Intestino; <b>reperfusión</b>; congestión previa</li></ul></div></div></div></div>"]},{"g":"Apoptosis","h":["<h4 class=\"mm\">Quando ocorre a apoptose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: APOPTOSIS\"><div class=\"org-root\">APOPTOSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#15803d;--cs:#dcfce7\"><div class=\"org-head\">Fisiológica<small>elimina células que ya no se necesitan</small></div><div class=\"org-leaf\"><h5>Embriogénesis</h5><ul><li><b>Membranas interdigitales</b></li><li>Organogénesis, involución de primordios</li></ul></div><div class=\"org-leaf\"><h5>Involución hormonal</h5><ul><li><b>Ciclo menstrual</b> (endometrio)</li><li><b>Menopausia</b> (atresia folicular)</li><li>Mama tras el <b>destete</b></li></ul></div><div class=\"org-leaf\"><h5>Recambio y defensa</h5><ul><li>Recambio de poblaciones proliferativas</li><li>Neutrófilos al final de la inflamación</li><li>Linfocitos <b>autorreactivos</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Patológica<small>células dañadas sin reparación</small></div><div class=\"org-leaf\"><h5>Daño del ADN</h5><ul><li>Radiación, quimioterapia</li><li>p53 detiene el ciclo o induce apoptosis</li></ul></div><div class=\"org-leaf\"><h5>Proteínas mal plegadas</h5><ul><li>Estrés del RE</li><li><b>Alzheimer, Parkinson</b></li></ul></div><div class=\"org-leaf\"><h5>Infecciones</h5><ul><li><b>Hepatitis viral</b> (cuerpos de Councilman)</li><li>Linfocitos T citotóxicos</li></ul></div><div class=\"org-leaf\"><h5>Atrofia patológica</h5><ul><li><b>Obstrucción de conductos</b>: páncreas, parótida, riñón</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#15803d\">Fisiológica</span><span style=\"background:#b3141c\">Patológica</span></div></div>","<h4 class=\"mm\">Organograma das vias da apoptose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: APOPTOSIS · ENZIMAS: CASPASAS Y ENDONUCLEASAS\"><div class=\"org-root\">APOPTOSIS · ENZIMAS: CASPASAS Y ENDONUCLEASAS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Vía intrínseca<small>mitocondrial · la más frecuente</small></div><div class=\"org-leaf\"><h5>Familia BCL2</h5><ul><li><b>Antiapoptóticas</b>: BCL2, BCLX, MCL1</li><li><b>Proapoptóticas</b>: BAX, BAK</li><li>Sensores BH3: BAD, BIM, BID</li></ul></div><div class=\"org-leaf\"><h5>Secuencia</h5><ul><li>Estrés: falta de factores de crecimiento, daño del ADN</li><li>BAX/BAK abren la membrana mitocondrial</li><li><b>Citocromo C sale al citosol</b></li><li>Apoptosoma → <b>caspasa 9</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Vía extrínseca<small>receptores de muerte</small></div><div class=\"org-leaf\"><h5>Receptores</h5><ul><li><b>TNFR1</b> (receptor de TNF tipo 1)</li><li><b>Fas (CD95)</b> + FasL</li></ul></div><div class=\"org-leaf\"><h5>Secuencia</h5><ul><li>Dominio de muerte → FADD</li><li><b>Caspasa 8</b></li><li>Inhibidor: FLIP</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Fase de ejecución<small>converge</small></div><div class=\"org-leaf\"><h5>Ejecutoras</h5><ul><li><b>Caspasas 3 y 6</b></li><li><b>Endonucleasas</b> fragmentan el ADN</li><li>Proteasas degradan citoesqueleto</li></ul></div><div class=\"org-leaf\"><h5>Final</h5><ul><li><b>Cuerpos apoptóticos</b></li><li>Fosfatidilserina expuesta → fagocitosis</li><li><b>Sin inflamación</b></li></ul></div></div></div><div class=\"org-note\">Citocromo C <b>não</b> é enzima: é a proteína que sai da mitocôndria e ativa o apoptossoma. As 2 enzimas são <b>caspasas y endonucleasas</b>.</div></div>","<h4 class=\"mm\">Necrose × apoptose × necroptose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: MUERTE CELULAR\"><div class=\"org-root\">MUERTE CELULAR</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Necrosis</div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Célula <b>aumentada</b></li><li>Picnosis → cariorrexis → cariólisis</li><li>Membrana <b>rota</b></li><li>Contenido sale → <b>inflamación</b></li><li>Siempre patológica</li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Apoptosis</div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Célula <b>reducida</b></li><li>Fragmentación en nucleosomas</li><li>Membrana <b>íntegra</b></li><li>Cuerpos apoptóticos, <b>sin inflamación</b></li><li>Fisiológica o patológica</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Necroptosis<small>híbrida</small></div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Programada como la apoptosis</li><li>Morfología de <b>necrosis</b></li><li><b>Sin caspasas</b></li><li>RIPK1, RIPK3, MLKL</li></ul></div></div></div></div>"]},{"g":"Acumulación: lípidos","h":["<h4 class=\"mm\">Organograma das acumulações</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ACUMULACIONES INTRACELULARES\"><div class=\"org-root\">ACUMULACIONES INTRACELULARES</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Lípidos<small>slide da professora</small></div><div class=\"org-leaf\"><h5>Triglicéridos</h5><ul><li><b>Esteatosis</b> (só citada no slide novo)</li><li>Hígado, corazón, músculo, riñón</li><li>Sudán / aceite rojo O</li></ul></div><div class=\"org-leaf\"><h5>Colesterol y ésteres</h5><ul><li><b>Aterosclerosis</b>: células espumosas</li><li><b>Xantomas</b></li><li><b>Colesterolosis</b> (vesícula en fresa)</li><li><b>Niemann-Pick tipo C</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Glucógeno<small>slide antigo · baixa prioridade</small></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li><b>Diabetes mellitus</b>: túbulos renales, hepatocitos, islotes</li><li><b>Glucogenosis</b> (enzimopatías)</li><li>Vacuolas claras</li><li><b>PAS</b> / carmín de <b>Best</b>: rosa-violáceo</li></ul></div></div><div class=\"org-col\" style=\"--c:#a21caf;--cs:#fae8ff\"><div class=\"org-head\">Clase 7<small>tema 04 desta apostila</small></div><div class=\"org-leaf\"><h5>Otras acumulaciones</h5><ul><li><b>Proteínas</b>: gotículas eosinófilas, Russell, Mallory, Lewy</li><li><b>Amiloidosis</b> (extracelular)</li><li><b>Calcificación</b> distrófica × metastásica</li></ul></div></div></div></div>","<h4 class=\"mm\">Esteatose: causa, mecanismo, aspecto</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ESTEATOSIS\"><div class=\"org-root\">ESTEATOSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Causas</div><div class=\"org-leaf\"><h5>Principales</h5><ul><li><b>Alcohol</b> (la más frecuente)</li><li><b>Diabetes</b> / síndrome metabólico</li><li><b>Obesidad</b></li><li>Toxinas, desnutrición proteica, hipoxia</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Mecanismo<small>6 pasos del metabolismo</small></div><div class=\"org-leaf\"><h5>Fallas posibles</h5><ul><li>↑ Entrada de ácidos grasos</li><li>↑ Síntesis o ↓ oxidación</li><li>↓ Apoproteínas</li><li>↓ Secreción de lipoproteínas</li></ul></div></div><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Morfología</div><div class=\"org-leaf\"><h5>Aspecto</h5><ul><li>Macro: hígado <b>grande, amarillo, graso</b></li><li>Micro: <b>vacuolas claras</b> que desplazan el núcleo</li><li>Micro/macrovesicular</li><li>Tinción: <b>Sudán IV, aceite rojo O</b></li></ul></div></div></div></div>","<h4 class=\"mm\">Organograma da aterosclerose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ATEROSCLEROSIS\"><div class=\"org-root\">ATEROSCLEROSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Factores de riesgo</div><div class=\"org-leaf\"><h5>No modificables</h5><ul><li><b>Edad</b></li><li><b>Sexo masculino</b></li><li><b>Antecedentes familiares</b></li><li>Genética</li></ul></div><div class=\"org-leaf\"><h5>Modificables</h5><ul><li><b>Hipercolesterolemia</b> (LDL ↑, HDL ↓)</li><li><b>HTA</b></li><li><b>Tabaco</b></li><li><b>DM</b> / síndrome metabólico</li><li>PCR (inflamación)</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Respuesta a la lesión<small>patogenia</small></div><div class=\"org-leaf\"><h5>Pasos</h5><ul><li>1. Lesión / disfunción <b>endotelial</b></li><li>2. Entrada y oxidación de <b>LDL</b></li><li>3. Adhesión de monocitos → <b>macrófagos</b></li><li>4. <b>Células espumosas</b> (macrófagos + CML)</li><li>5. Migración y proliferación de <b>CML</b></li><li>6. Matriz extracelular: <b>placa</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Placa<small>túnica íntima</small></div><div class=\"org-leaf\"><h5>Componentes</h5><ul><li><b>Capa fibrosa</b> (CML, colágeno)</li><li><b>Núcleo necrótico</b>: lípidos, restos, células espumosas</li><li>Hombro: macrófagos, linfocitos T</li></ul></div><div class=\"org-leaf\"><h5>Estable × vulnerable</h5><ul><li>Estable: capa <b>gruesa</b>, poco lípido</li><li>Vulnerable: capa <b>fina</b>, mucho lípido e inflamación</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Complicaciones<small>cambios agudos</small></div><div class=\"org-leaf\"><h5>De la placa</h5><ul><li><b>Rotura, ulceración, erosión</b> → trombosis</li><li><b>Hemorragia</b> intraplaca</li><li><b>Ateroembolia</b></li><li><b>Calcificación distrófica</b></li></ul></div><div class=\"org-leaf\"><h5>Del vaso</h5><ul><li><b>Aneurisma</b> (debilita la media)</li><li>Estenosis → isquemia</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Riesgo</span><span style=\"background:#c2410c\">Patogenia</span><span style=\"background:#a16207\">Placa</span><span style=\"background:#4338ca\">Complicaciones</span></div></div>"]},{"g":"Proteínas, amiloide, calcio (Clase 7)","h":["<h4 class=\"mm\">Organograma: acumulação de proteínas</h4><div aria-label=\"Organograma: PROTEÍNAS · gotículas eosinófilas\" class=\"org\" role=\"img\"><div class=\"org-root\">PROTEÍNAS · gotículas eosinófilas</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:5\"><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Reabsorción tubular<small>riñón</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Proteinuria → túbulo proximal reabsorbe más por <b>pinocitosis</b></li><li><b>Gotículas hialinas rosadas</b></li><li><b>REVERSIBLE</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Inmunoglobulinas<small>célula plasmática</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Exceso de Ig distiende el RE</li><li><b>Cuerpos de Russell</b></li><li>Inclusiones eosinófilas homogéneas</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Transporte defectuoso<small>plegamiento lento</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li><b>Deficiencia de α1-antitripsina</b></li><li>Glóbulos eosinófilos en el RE del <b>hepatocito</b> (PAS +)</li><li>Pulmón sin enzima → <b>ENFISEMA</b></li><li>Estrés del RE → apoptosis</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Citoesqueleto<small>filamentos intermedios</small></div><div class=\"org-leaf\"><h5>Queratina</h5><ul><li><b>Hialina alcohólica / de Mallory</b></li><li>Hepatopatía alcohólica</li></ul></div><div class=\"org-leaf\"><h5>Neurofilamentos</h5><ul><li><b>Ovillos neurofibrilares</b></li><li>Alzheimer · tinción de plata</li></ul></div><div class=\"org-leaf\"><h5>α-sinucleína</h5><ul><li><b>Cuerpos de Lewy</b></li><li>Demencia de cuerpos de Lewy · IHQ ubiquitina</li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Agregación anómala<small>proteinopatías</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Proteínas <b>mal plegadas</b></li><li>Depósitos IC, EC o ambos</li><li><b>AMILOIDOSIS</b>: fibrillas insolubles extracelulares</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#0f766e\">1 Riñón</span><span style=\"background:#4338ca\">2 Ig</span><span style=\"background:#a16207\">3 α1-AT</span><span style=\"background:#b3141c\">4 Citoesqueleto</span><span style=\"background:#7a3fe0\">5 Amiloide</span></div></div>","<h4 class=\"mm\">Organograma da amiloidose</h4><div aria-label=\"Organograma: AMILOIDOSIS\" class=\"org\" role=\"img\"><div class=\"org-root\">AMILOIDOSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Primaria<small>sistémica · AL</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Proliferación <b>clonal</b> de células plasmáticas</li><li>Ig anómala: <b>cadena ligera (AL)</b></li><li><b>Mieloma múltiple</b></li><li>Órganos: <b>corazón</b>, tubo digestivo, vías respiratorias, nervios periféricos, piel, <b>lengua</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Secundaria reactiva<small>sistémica · AA</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Complicación de <b>inflamación crónica</b></li><li>Proteína <b>AA</b> (asociada a amiloide)</li><li><b>Artritis reumatoide</b>, <b>EII</b> (Crohn, colitis ulcerosa)</li><li>Órganos: <b>riñón</b>, hígado, bazo, ganglios, suprarrenales, tiroides</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">β-amiloide<small>localizada</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li><b>Enfermedad de Alzheimer</b></li><li>Placas cerebrales</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Otras</div><div class=\"org-leaf\"><h5>Lista del slide</h5><ul><li>Hereditaria o familiar</li><li><b>Hemodiálisis</b>: microglobulina β2 → <b>túnel carpiano</b></li><li><b>Endocrina</b>: tumores tiroideos, pancreáticos, feocromocitoma</li><li><b>Senil</b>: corazón</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#4338ca\">3 formas más frecuentes: AL · AA · β</span></div><div class=\"org-note\">Rim: o mais frequente e o mais grave. Coração: o principal órgão na amiloidose <b>senil</b>.</div></div>","<h4 class=\"mm\">Organograma da calcificação patológica</h4><div aria-label=\"Organograma: CALCIFICACIÓN PATOLÓGICA\" class=\"org\" role=\"img\"><div class=\"org-root\">CALCIFICACIÓN PATOLÓGICA</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Distrófica<small>tejido muerto o lesionado</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Calcemia <b>NORMAL</b></li><li>Generalmente <b>IRREVERSIBLE</b></li><li>Necrosis (todas), <b>ateromas</b>, válvulas dañadas o de ancianos, trombos, hematomas, tumores, <b>Mönckeberg</b></li></ul></div><div class=\"org-leaf\"><h5>Patogenia</h5><ul><li>Proteína desnaturalizada + fosfato + Ca²⁺ → fosfato de calcio</li><li><b>Iniciación</b>: mitocondrias o vesículas</li><li><b>Propagación</b>: cristales</li></ul></div><div class=\"org-leaf\"><h5>Morfología</h5><ul><li>Macro: <b>\"depósitos arenosos\"</b> blanquecinos</li><li>H&amp;E: <b>basófilo</b>, granular, amorfo</li><li>Hueso heterotópico con el tiempo</li><li><b>Cuerpos de psamoma</b> (cáncer papilar)</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Metastásica<small>tejido normal</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li><b>HIPERCALCEMIA</b> siempre</li><li><b>REVERSIBLE</b> si se corrige la causa</li><li>En general sin disfunción clínica</li></ul></div><div class=\"org-leaf\"><h5>4 causas</h5><ul><li>↑ <b>PTH</b> (hiperparatiroidismo)</li><li><b>Resorción ósea</b>: mieloma, metástasis, inmovilización</li><li>Trastornos de <b>vitamina D</b></li><li><b>Insuficiencia renal crónica</b></li><li>(+ síndrome leche-alcalinos)</li></ul></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li>Mucosa <b>gástrica</b>, <b>riñones</b>, <b>pulmones</b></li><li>Arterias sistémicas, venas pulmonares, sinovial</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Distrófica: Ca normal</span><span style=\"background:#4338ca\">Metastásica: Ca alto</span></div></div>"]}]};
